const getItemSizeOptions = (item = {}) => {
  const rawSizes = Array.isArray(item?.sizeOptions)
    ? item.sizeOptions
    : Array.isArray(item?.sizes)
      ? item.sizes
      : typeof item?.sizes === 'string'
        ? item.sizes.split(',')
        : [];

  return rawSizes
    .map((value) => String(value || '').trim())
    .filter(Boolean);
};

// Per-size stock support. A listing can carry a `sizeStock` map
// ({ "S": 5, "M": 0, "UK 7": 3 }) so each size/variant of the same product
// tracks its own quantity. Buyers can only order sizes that still have stock;
// when a size hits 0 it becomes un-orderable while the rest stay available.
const getItemSizeStockMap = (item = {}) => {
  const raw = item?.sizeStock;
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const entries = Object.entries(raw)
    .map(([key, value]) => [String(key).trim(), normalizeListingQuantity(value, 0)])
    .filter(([key]) => Boolean(key));
  return entries.length ? Object.fromEntries(entries) : null;
};

const hasItemSizeStock = (item = {}) => Boolean(getItemSizeStockMap(item));

const getItemSizeStock = (item = {}, size = '') => {
  const stockMap = getItemSizeStockMap(item);
  if (!stockMap) return null;
  const target = String(size || '').trim().toLowerCase();
  const matchKey = Object.keys(stockMap).find((key) => key.toLowerCase() === target);
  return matchKey ? stockMap[matchKey] : 0;
};

const isItemSizeSoldOut = (item = {}, size = '') => {
  const stock = getItemSizeStock(item, size);
  if (stock === null) return false;
  return stock <= 0;
};

// Sizes that still have stock (or every size if the listing has no per-size
// stock map). Used to pick a sensible default selected size and to decide
// when the whole listing is sold out.
const getItemInStockSizes = (item = {}) => {
  const sizes = getItemSizeOptions(item);
  const stockMap = getItemSizeStockMap(item);
  if (!stockMap) return sizes;
  return sizes.filter((size) => (getItemSizeStock(item, size) || 0) > 0);
};

// Sum the per-size stock values for the AI Quick Lister draft so the overall
// listing quantity always equals the total across every size/variant.
const sumBulkSizeStock = (sizes = [], stockMap = {}) => (Array.isArray(sizes) ? sizes : []).reduce(
  (total, size) => total + Math.max(parseInt(stockMap?.[size], 10) || 0, 0),
  0,
);

// Per-size pricing support. A listing can carry a `sizePrices` map
// ({ "25kg": 80, "50kg": 150 }) so the same product can be sold in several
// packing sizes at different prices. A size with no explicit price falls back
// to the listing's base price.
const getItemSizePriceMap = (item = {}) => {
  const raw = item?.sizePrices;
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const entries = Object.entries(raw)
    .map(([key, value]) => [String(key).trim(), Number(String(value ?? '').replace(/[^\d.]/g, ''))])
    .filter(([key, amount]) => Boolean(key) && Number.isFinite(amount) && amount > 0);
  return entries.length ? Object.fromEntries(entries) : null;
};

const hasItemSizePrices = (item = {}) => Boolean(getItemSizePriceMap(item));

// The price for a single size/variant, or null when the listing has no
// per-size pricing (or that size has no explicit price).
const getItemSizePrice = (item = {}, size = '') => {
  const priceMap = getItemSizePriceMap(item);
  if (!priceMap) return null;
  const target = String(size || '').trim().toLowerCase();
  const matchKey = Object.keys(priceMap).find((key) => key.toLowerCase() === target);
  return matchKey ? priceMap[matchKey] : null;
};

// Detail-modal size props bundle. Spreading this into an onOpenItemDetails
// payload carries the listing's sizes, per-size stock and per-size pricing
// into the buyer detail modal for ANY market. Returns an empty object for
// listings with no sizes so it is safe to spread into every market builder.
const getItemDetailSizeProps = (item = {}) => {
  const sizeOptions = getItemSizeOptions(item);
  if (!sizeOptions.length) return {};
  return {
    currency: item.currency,
    sizeOptions,
    sizeStock: item.sizeStock,
    sizePrices: item.sizePrices,
    defaultSelectedSize: item.selectedSize || getItemInStockSizes(item)[0] || sizeOptions[0] || '',
  };
};

