// --- Chat media storage ------------------------------------------------
// Large chat attachments (photos, voice notes, videos, documents) used to be
// base64-encoded straight into the message body, which broke for anything but
// tiny files. Instead we upload the raw bytes to a public Supabase Storage
// bucket and keep only the short public URL in the message.
const CHAT_MEDIA_BUCKET = 'chat-media';

const CHAT_MEDIA_EXT_BY_MIME = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/gif': 'gif',
  'image/webp': 'webp',
  'image/heic': 'heic',
  'audio/webm': 'webm',
  'audio/ogg': 'ogg',
  'audio/mp4': 'm4a',
  'audio/mpeg': 'mp3',
  'video/mp4': 'mp4',
  'video/webm': 'webm',
  'video/quicktime': 'mov',
  'application/pdf': 'pdf',
};

// Decode a `data:` URL into a Blob without inflating it through a string copy
// more than necessary.
const dataUrlToBlob = (dataUrl) => {
  const commaIndex = String(dataUrl).indexOf(',');
  if (commaIndex === -1) throw new Error('Invalid data URL');
  const header = dataUrl.slice(0, commaIndex);
  const payload = dataUrl.slice(commaIndex + 1);
  const mime = (header.match(/^data:([^;]+)/) || [])[1] || 'application/octet-stream';
  const isBase64 = /;base64/i.test(header);
  if (!isBase64) {
    return new Blob([decodeURIComponent(payload)], { type: mime });
  }
  const binary = atob(payload);
  const length = binary.length;
  const bytes = new Uint8Array(length);
  for (let i = 0; i < length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return new Blob([bytes], { type: mime });
};

// Upload a `data:` URL to the chat-media bucket and return its public URL.
// Returns null (and the caller falls back to inline) when Supabase is not
// configured.
const uploadChatMediaFromDataUrl = async (dataUrl, { userEmail = '', type = 'file', name = '', mimeType = '' } = {}) => {
  if (!hasSupabaseEnv || !supabase) return null;
  const blob = dataUrlToBlob(dataUrl);
  const mime = mimeType || blob.type || 'application/octet-stream';
  let ext = '';
  if (name && name.includes('.')) {
    ext = name.split('.').pop();
  }
  if (!ext) {
    ext = CHAT_MEDIA_EXT_BY_MIME[mime] || (mime.split('/')[1] || 'bin');
  }
  const safeExt = String(ext || 'bin').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 8) || 'bin';
  const folder = sanitizeStorageSegment(userEmail || 'user');
  const fileName = `${Date.now()}-${Math.random().toString(36).slice(2)}.${safeExt}`;
  const filePath = `${folder}/${sanitizeStorageSegment(type) || 'file'}/${fileName}`;
  const { error: uploadError } = await supabase.storage
    .from(CHAT_MEDIA_BUCKET)
    .upload(filePath, blob, { cacheControl: '3600', upsert: false, contentType: mime });
  if (uploadError) throw uploadError;
  const { data } = supabase.storage.from(CHAT_MEDIA_BUCKET).getPublicUrl(filePath);
  return data?.publicUrl || null;
};

// --- Realtime presence -------------------------------------------------
// Tracks which user emails are *actually* connected (a browser/app session is
// open) using a Supabase Realtime presence channel. The chat UI reads this so
// it only shows "Online" for people who are genuinely present, instead of
// faking it for every seller/buyer.
const presenceOnlineEmails = new Set();
const presenceListeners = new Set();
let presenceChannel = null;
let presenceCurrentEmail = '';
// {email → threadId} — who is currently typing in which thread
let presenceTypingMap = {};
const presenceTypingListeners = new Set();
const notifyPresenceTypingListeners = () => {
  presenceTypingListeners.forEach((l) => { try { l({ ...presenceTypingMap }); } catch (_) { /* ignore */ } });
};

const notifyPresenceListeners = () => {
  presenceListeners.forEach((listener) => {
    try { listener(new Set(presenceOnlineEmails)); } catch (_) { /* ignore */ }
  });
};

const recomputePresenceFromState = (state) => {
  const previouslyOnline = new Set(presenceOnlineEmails);
  presenceOnlineEmails.clear();
  const nowIso = new Date().toISOString();
  const newTypingMap = {};
  Object.values(state || {}).forEach((entries) => {
    (entries || []).forEach((entry) => {
      const email = normalizeEmail(entry?.email || '');
      if (email) {
        presenceOnlineEmails.add(email);
        // Anyone we can see online is "seen" right now — keep it fresh so the
        // moment they drop off we already have an accurate last-seen.
        lastSeenCache.set(email, nowIso);
        if (entry.typing) newTypingMap[email] = entry.typing;
      }
    });
  });
  const prevJson = JSON.stringify(presenceTypingMap);
  presenceTypingMap = newTypingMap;
  if (JSON.stringify(newTypingMap) !== prevJson) notifyPresenceTypingListeners();
  // Anyone who was online a moment ago but isn't now just went offline.
  // Record their real last-seen from *our* vantage point (works even when
  // their own browser never wrote a heartbeat).
  let leaverWrote = false;
  previouslyOnline.forEach((email) => {
    if (!presenceOnlineEmails.has(email)) {
      persistLastSeen(email, nowIso);
      leaverWrote = true;
    }
  });
  notifyPresenceListeners();
  if (leaverWrote) notifyLastSeenListeners();
};

const leavePresence = () => {
  // Stamp a final "last seen" the moment we disconnect, then stop the beat.
  stopLastSeenHeartbeat(presenceCurrentEmail);
  if (presenceChannel) {
    try { presenceChannel.untrack(); } catch (_) { /* ignore */ }
    try { supabase?.removeChannel(presenceChannel); } catch (_) { /* ignore */ }
    presenceChannel = null;
  }
  presenceCurrentEmail = '';
};

const joinPresence = (rawEmail) => {
  const email = normalizeEmail(rawEmail);
  if (!hasSupabaseEnv || !supabase || !email) return;
  if (presenceChannel && presenceCurrentEmail === email) return;
  // Re-join cleanly on account switch / sign-out -> sign-in.
  leavePresence();
  presenceCurrentEmail = email;
  const channel = supabase.channel('svs-presence', {
    config: { presence: { key: email } },
  });
  presenceChannel = channel;
  const sync = () => recomputePresenceFromState(channel.presenceState());
  channel
    .on('presence', { event: 'sync' }, sync)
    .on('presence', { event: 'join' }, sync)
    .on('presence', { event: 'leave' }, sync)
    .subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        channel.track({ email, online_at: new Date().toISOString() });
      }
    });
  // Persist a real "last seen" heartbeat so others can see it once we leave.
  ensureLastSeenChannel();
  startLastSeenHeartbeat(email);
};

// Broadcast that the current user is typing in a specific thread.
// Call with null / '' to clear the typing state (auto-cleared by the chat
// input after 3 s of no keypress so it always expires naturally).
const broadcastTyping = (threadId) => {
  if (!presenceChannel || !presenceCurrentEmail) return;
  presenceChannel.track({
    email: presenceCurrentEmail,
    online_at: new Date().toISOString(),
    typing: threadId || null,
  });
};

// React hook: subscribe to the live set of online emails.
const usePresence = () => {
  const [onlineEmails, setOnlineEmails] = useState(() => new Set(presenceOnlineEmails));
  useEffect(() => {
    const listener = (next) => setOnlineEmails(next);
    presenceListeners.add(listener);
    setOnlineEmails(new Set(presenceOnlineEmails));
    return () => { presenceListeners.delete(listener); };
  }, []);
  return onlineEmails;
};

// React hook: subscribe to the live typing map { email → threadId }.
const useTyping = () => {
  const [typingMap, setTypingMap] = useState(() => ({ ...presenceTypingMap }));
  useEffect(() => {
    const listener = (next) => setTypingMap(next);
    presenceTypingListeners.add(listener);
    setTypingMap({ ...presenceTypingMap });
    return () => presenceTypingListeners.delete(listener);
  }, []);
  return typingMap;
};

// --- Last-seen heartbeat --------------------------------------------------
// Presence (above) only knows who is connected *right now*. To show
// "last seen … ago" once someone disconnects, we persist a heartbeat
// timestamp per registered user in `user_presence` and read it back for the
// counterparty. Real data — no faked timestamps.
const LAST_SEEN_TABLE = 'user_presence';
const lastSeenCache = new Map(); // normalized email -> ISO timestamp
const lastSeenListeners = new Set();
let lastSeenChannel = null;
let lastSeenHeartbeatTimer = null;

const notifyLastSeenListeners = () => {
  const snapshot = new Map(lastSeenCache);
  lastSeenListeners.forEach((listener) => {
    try { listener(snapshot); } catch (_) { /* ignore */ }
  });
};

const recordLastSeenRow = (row) => {
  const email = normalizeEmail(row?.email || '');
  const ts = row?.last_seen_at || row?.updated_at || '';
  if (email && ts) lastSeenCache.set(email, ts);
};

const ensureLastSeenChannel = () => {
  if (!hasSupabaseEnv || !supabase || lastSeenChannel) return;
  lastSeenChannel = supabase
    .channel('svs-last-seen')
    .on('postgres_changes', { event: '*', schema: 'public', table: LAST_SEEN_TABLE }, (payload) => {
      recordLastSeenRow(payload.new || payload.old);
      notifyLastSeenListeners();
    })
    .subscribe();
};

const fetchLastSeenFor = async (emails) => {
  if (!hasSupabaseEnv || !supabase) return;
  const list = Array.from(new Set((emails || []).map(normalizeEmail).filter(Boolean)));
  if (!list.length) return;
  try {
    const { data } = await supabase.from(LAST_SEEN_TABLE).select('email, last_seen_at').in('email', list);
    (data || []).forEach(recordLastSeenRow);
    notifyLastSeenListeners();
  } catch (_) { /* ignore */ }
};

const persistLastSeen = (rawEmail, stamp) => {
  const email = normalizeEmail(rawEmail);
  if (!email) return;
  const at = stamp || new Date().toISOString();
  lastSeenCache.set(email, at);
  if (!hasSupabaseEnv || !supabase) return;
  try {
    supabase.from(LAST_SEEN_TABLE)
      .upsert({ email, last_seen_at: at, updated_at: at }, { onConflict: 'email' })
      .then(() => {}, () => {});
  } catch (_) { /* ignore */ }
};

const writeLastSeen = (rawEmail) => {
  const email = normalizeEmail(rawEmail);
  if (!email) return;
  persistLastSeen(email, new Date().toISOString());
  notifyLastSeenListeners();
};

const startLastSeenHeartbeat = (rawEmail) => {
  const email = normalizeEmail(rawEmail);
  if (!email) return;
  writeLastSeen(email);
  if (lastSeenHeartbeatTimer) clearInterval(lastSeenHeartbeatTimer);
  lastSeenHeartbeatTimer = setInterval(() => writeLastSeen(email), 30000);
};

const stopLastSeenHeartbeat = (rawEmail) => {
  if (lastSeenHeartbeatTimer) { clearInterval(lastSeenHeartbeatTimer); lastSeenHeartbeatTimer = null; }
  // Final stamp so "last seen" is accurate the moment we go offline.
  writeLastSeen(rawEmail);
};

// Turn an ISO timestamp into a friendly "last seen …" label.
const formatLastSeen = (iso) => {
  const ts = Date.parse(iso || '');
  if (!ts) return '';
  const diffMs = Date.now() - ts;
  if (diffMs < 60000) return 'last seen just now';
  const mins = Math.floor(diffMs / 60000);
  if (mins < 60) return `last seen ${mins} min ago`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `last seen ${hours} hour${hours === 1 ? '' : 's'} ago`;
  const days = Math.floor(hours / 24);
  if (days === 1) return 'last seen yesterday';
  if (days < 7) return `last seen ${days} days ago`;
  try {
    return `last seen ${new Date(ts).toLocaleDateString(undefined, { day: 'numeric', month: 'short' })}`;
  } catch (_) { return 'last seen a while ago'; }
};

// React hook: subscribe to last-seen timestamps for the given emails.
const useLastSeen = (emails) => {
  const [map, setMap] = useState(() => new Map(lastSeenCache));
  const key = (Array.isArray(emails) ? emails : [emails])
    .map(normalizeEmail).filter(Boolean).sort().join(',');
  useEffect(() => {
    ensureLastSeenChannel();
    const listener = (next) => setMap(next);
    lastSeenListeners.add(listener);
    setMap(new Map(lastSeenCache));
    const list = key ? key.split(',') : [];
    if (list.length) fetchLastSeenFor(list);
    // Poll as a fallback in case Realtime updates are not delivered, and to
    // keep the relative "last seen … ago" labels fresh as time passes.
    const poll = setInterval(() => {
      if (list.length) fetchLastSeenFor(list);
      else notifyLastSeenListeners();
    }, 20000);
    return () => {
      lastSeenListeners.delete(listener);
      clearInterval(poll);
    };
  }, [key]);
  return map;
};

const normalizeReviewComment = (value) => String(value || '')
  .replace(/\s+/g, ' ')
  .trim();

const normalizeReviewerName = (value, reviewerEmail = '') => {
  const trimmedName = String(value || '').trim();

  if (trimmedName) {
    return trimmedName.slice(0, 50);
  }

  const normalizedEmail = normalizeEmail(reviewerEmail);

  if (normalizedEmail.includes('@')) {
    return normalizedEmail.split('@')[0].slice(0, 50);
  }

  return 'Guest';
};

const containsHarshReviewContent = (value) => {
  const normalizedValue = normalizeReviewComment(value).toLowerCase();

  if (!normalizedValue) {
    return false;
  }

  return HARSH_REVIEW_TERMS.some((term) => {
    const expression = new RegExp(`(^|[^a-z])${term}([^a-z]|$)`, 'i');
    return expression.test(normalizedValue);
  });
};

const getProductReviewItemKey = (item) => {
  if (item?.wishlistItem?.id) {
    return item.wishlistItem.id;
  }

  if (item?.cartItem?.id) {
    return item.cartItem.id;
  }

  return `${sanitizeStorageSegment(item?.marketName)}:${sanitizeStorageSegment(item?.title)}`;
};

const createProductReview = ({ itemKey, rating, comment, reviewerName, reviewerEmail = '' }) => ({
  id: `review-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
  itemKey,
  rating: Math.min(5, Math.max(1, Number(rating) || 5)),
  comment: normalizeReviewComment(comment),
  reviewerName: normalizeReviewerName(reviewerName, reviewerEmail),
  reviewerEmail: normalizeEmail(reviewerEmail),
  moderationStatus: 'approved',
  createdAt: new Date().toISOString(),
});

const sortProductReviews = (reviews) => [...reviews].sort((leftReview, rightReview) => (
  Date.parse(rightReview.createdAt || '') - Date.parse(leftReview.createdAt || '')
));

const mapProductReviewRecord = (record) => ({
  id: record.id,
  itemKey: record.item_key,
  rating: Math.min(5, Math.max(1, Number(record.rating) || 5)),
  comment: normalizeReviewComment(record.comment),
  reviewerName: normalizeReviewerName(record.reviewer_name, record.reviewer_email),
  reviewerEmail: normalizeEmail(record.reviewer_email || ''),
  moderationStatus: String(record.moderation_status || 'approved'),
  createdAt: record.created_at || new Date().toISOString(),
});

const toProductReviewRecord = (review) => ({
  item_key: review.itemKey,
  rating: review.rating,
  comment: review.comment,
  reviewer_name: review.reviewerName,
  reviewer_email: review.reviewerEmail || null,
  moderation_status: review.moderationStatus || 'approved',
});

const getStoredApprovedProductReviews = (itemKey) => sortProductReviews(
  getStoredProductReviews().filter((review) => review.itemKey === itemKey && review.moderationStatus !== 'rejected'),
);

const buildProductReviewSummaryMap = (reviews = []) => {
  const groupedSummaries = reviews.reduce((summaryMap, review) => {
    if (!review?.itemKey || review.moderationStatus === 'rejected') {
      return summaryMap;
    }

    const currentSummary = summaryMap[review.itemKey] || { totalRating: 0, reviewCount: 0 };
    const nextSummary = {
      totalRating: currentSummary.totalRating + (Number(review.rating) || 0),
      reviewCount: currentSummary.reviewCount + 1,
    };

    summaryMap[review.itemKey] = nextSummary;
    return summaryMap;
  }, {});

  return Object.fromEntries(
    Object.entries(groupedSummaries).map(([itemKey, summary]) => [
      itemKey,
      {
        averageRating: summary.reviewCount ? Number((summary.totalRating / summary.reviewCount).toFixed(1)) : 0,
        reviewCount: summary.reviewCount,
      },
    ]),
  );
};

const getProductReviewSummary = (reviewSummaryMap, itemKey) => reviewSummaryMap?.[itemKey] || {
  averageRating: 0,
  reviewCount: 0,
};

const getMarketplaceItemSaveErrorMessage = (errorMessage) => {
  const normalizedMessage = String(errorMessage || '').toLowerCase();

  if (normalizedMessage.includes('marketplace_items_market_key_check')) {
    return `Item save failed: ${errorMessage}. Rerun supabase/seller-marketplace.sql so the ${SELLER_ITEMS_TABLE} market_key constraint includes the selected market.`;
  }

  if (normalizedMessage.includes('quantity')) {
    return `Item save failed: ${errorMessage}. Run supabase/add-marketplace-item-quantity.sql, then try again.`;
  }

  if (normalizedMessage.includes('details_json')) {
    return `Item save failed: ${errorMessage}. Rerun supabase/seller-marketplace.sql so seller listing metadata fields are available.`;
  }

  return `Item save failed: ${errorMessage}. Create or update the ${SELLER_ITEMS_TABLE} table before using seller uploads.`;
};

const cudyBluePrimaryButtonClassName = 'svs-test-primary-button';
const cudyBluePrimaryOutlineClassName = 'svs-test-primary-outline';
const cudyBluePrimaryIconClassName = 'svs-test-primary-icon';

const formatDate = (value, locale = 'en-US') =>
  new Date(value).toLocaleDateString(locale, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });

// Full date + time (including seconds) for any timestamp that records when a
// user actually did something — account creation, orders, transactions,
// admin actions, audit log entries, messages, reviews. Options are spelled
// out explicitly (rather than relying on toLocaleString() defaults) so
// seconds are guaranteed to show regardless of browser/locale.
const formatTimestampWithSeconds = (value) => {
  if (!value) return '—';
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return '—';
  return parsed.toLocaleString(undefined, {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  });
};

const formatListingDateLabel = (value) => {
  const trimmedValue = String(value || '').trim();

  if (!trimmedValue) {
    return '';
  }

  const isoDateMatch = trimmedValue.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (isoDateMatch) {
    return `${isoDateMatch[1]}/${isoDateMatch[2]}/${isoDateMatch[3]}`;
  }

  const parsedDate = new Date(trimmedValue.includes('T') ? trimmedValue : `${trimmedValue}T00:00:00`);

  if (Number.isNaN(parsedDate.getTime())) {
    return trimmedValue;
  }

  const year = parsedDate.getFullYear();
  const month = String(parsedDate.getMonth() + 1).padStart(2, '0');
  const day = String(parsedDate.getDate()).padStart(2, '0');

  return `${year}/${month}/${day}`;
};

const getSellerListingValidationMessage = (formState) => {
  if (formState.marketKey === 'beverages') {
    const hasCategory = String(formState.beverageCategory || '').trim();
    const hasType = String(formState.beverageType || '').trim();
    const hasBrand = String(formState.brand || '').trim();
    const hasVolume = String(formState.volume || '').trim();
    const hasDescription = String(formState.description || '').trim();
    if (hasCategory && hasType && hasBrand && hasVolume && hasDescription) {
      return '';
    }
    return 'For beverage listings, select the beverage category, type, brand, volume, and add a short description before publishing.';
  }
  if (formState.marketKey !== 'groceries') {
    if (formState.marketKey !== 'tickets') {
      // Generic spec-driven validation for any other registered market.
      const spec = getMarketFieldSpec(formState.marketKey);
      if (spec) {
        const missing = spec.fields
          .filter((field) => field.required && !String(formState[field.name] || '').trim())
          .map((field) => field.label.toLowerCase());
        if (missing.length) {
          return `For ${spec.title.replace(/ Listing Details$/, '')} listings, please complete: ${missing.join(', ')}.`;
        }
      }
      return '';
    }
    // ...existing tickets validation code...
    const category = String(formState.ticketCategory || '').trim();
    const hasCategory = category;
    const hasCountry = String(formState.ticketCountry || '').trim();
    const hasLocation = String(formState.ticketLocation || '').trim();
    const hasDate = String(formState.ticketDate || '').trim();
    const isMoviesCategory = category === 'Movies';
    const isConcertsCategory = category === 'Concerts';
    const isSportsCategory = category === 'Sports';
    const isTravelCategory = category === 'Travel';
    const needsDate = isMoviesCategory || isConcertsCategory || isSportsCategory;
    const needsProvider = isConcertsCategory || isSportsCategory || isTravelCategory;
    const hasCity = String(formState.ticketCity || '').trim();
    const hasProvider = String(formState.ticketProvider || '').trim();
    const hasGenre = String(formState.ticketGenre || '').trim();
    const hasLanguage = String(formState.ticketLanguage || '').trim();
    const hasShowtime = String(formState.ticketShowtime || '').trim();
    if (hasCategory
      && hasCountry
      && hasLocation
      && hasGenre
      && (!needsDate || hasDate)
      && (!needsProvider || hasProvider)
      && (!isMoviesCategory || (hasCity && hasLanguage && hasShowtime))) {
      return '';
    }
    if (!hasCategory) {
      return 'Select a bookings category before publishing this listing.';
    }
    if (!hasCountry || !hasLocation) {
      return 'For bookings and tickets listings, choose a country and add venue/location before publishing.';
    }
    if (!hasGenre) {
      return `Add a genre/type for ${category} listings so the sidebar filter can match this listing.`;
    }
    if (needsDate && !hasDate) {
      return `Add an event date for ${category} listings so date filters can match this listing.`;
    }
    if (needsProvider && !hasProvider) {
      return `Add a provider/organizer for ${category} listings before publishing.`;
    }
    if (isMoviesCategory) {
      return 'For movie listings, add city, language, and showtime so movie sidebar filters can match this listing.';
    }
    return '';
  }
  const hasCategory = String(formState.categoryKey || '').trim();
  const hasBrand = String(formState.brand || '').trim();
  const hasVolume = String(formState.volume || '').trim();
  const hasFreshness = String(formState.freshness || '').trim();
  if (hasCategory && hasBrand && hasVolume && hasFreshness) {
    return '';
  }
  return 'For grocery listings, select the grocery category and add the brand, pack size, and freshness details before publishing.';
};

// Sanitize the optional multi-size fields from a seller form into the shape
// the buyer side reads: `sizes` (array), `sizeStock` (map) and `sizePrices`
// (map, only sizes with a real price > 0). Returns an empty object for
// sizeless listings so the details_json stays clean.
const buildSizeDetailFields = (formState = {}) => {
  const sizes = Array.isArray(formState.sizes)
    ? formState.sizes.map((value) => String(value || '').trim()).filter(Boolean)
    : [];
  if (!sizes.length) return {};

  const rawStock = formState.sizeStock && typeof formState.sizeStock === 'object' ? formState.sizeStock : {};
  const rawPrices = formState.sizePrices && typeof formState.sizePrices === 'object' ? formState.sizePrices : {};

  const sizeStock = {};
  const sizePrices = {};
  sizes.forEach((size) => {
    const qty = parseInt(String(rawStock[size] ?? '').replace(/[^\d]/g, ''), 10);
    sizeStock[size] = Number.isFinite(qty) ? qty : 0;
    const amount = Number(String(rawPrices[size] ?? '').replace(/[^\d.]/g, ''));
    if (Number.isFinite(amount) && amount > 0) sizePrices[size] = amount;
  });

  const result = { sizes, sizeStock };
  if (Object.keys(sizePrices).length) result.sizePrices = sizePrices;
  return result;
};

const buildSellerItemBaseDetailsJson = (formState) => {
  const sharedFields = {
    currency: SUPPORTED_CURRENCIES.some((entry) => entry.code === formState.currency) ? formState.currency : 'USD',
    // Spread into every branch below (including the no-spec fallback) so
    // availability data set on General Labour / Home-Care listings survives
    // a save made through the generic dashboard "Edit" modal, which rebuilds
    // details_json from formState and would otherwise silently drop any
    // field that isn't part of that market's MARKET_FIELD_SPEC entry.
    ...(Array.isArray(formState.availableDays) && formState.availableDays.length ? { availableDays: formState.availableDays } : {}),
    ...(formState.availabilityHours && typeof formState.availabilityHours === 'object' && Object.keys(formState.availabilityHours).length ? { availabilityHours: formState.availabilityHours } : {}),
    ...(Array.isArray(formState.unavailableDates) && formState.unavailableDates.length ? { unavailableDates: formState.unavailableDates } : {}),
  };
  if (formState.marketKey === 'groceries') {
    const categoryKey = String(formState.categoryKey || '').trim();
    const categoryTitle = getGroceriesCategoryTitle(categoryKey);
    return Object.fromEntries(
      Object.entries({
        ...sharedFields,
        categoryKey,
        category: categoryTitle,
        brand: String(formState.brand || '').trim(),
        volume: String(formState.volume || '').trim(),
        freshness: String(formState.freshness || '').trim(),
        storage: String(formState.storage || '').trim(),
        origin: String(formState.origin || '').trim(),
        expiryDate: String(formState.expiryDate || '').trim(),
        discount: String(formState.discount || '').trim(),
      }).filter(([, value]) => Boolean(String(value || '').trim())),
    );
  }
  if (formState.marketKey === 'beverages') {
    return Object.fromEntries(
      Object.entries({
        ...sharedFields,
        beverageCategory: String(formState.beverageCategory || '').trim(),
        beverageType: String(formState.beverageType || '').trim(),
        brand: String(formState.brand || '').trim(),
        volume: String(formState.volume || '').trim(),
        origin: String(formState.origin || '').trim(),
        description: String(formState.description || '').trim(),
      }).filter(([, value]) => Boolean(String(value || '').trim())),
    );
  }
  if (formState.marketKey === 'tickets') {
    const ticketCategory = String(formState.ticketCategory || '').trim();
    const isMoviesCategory = ticketCategory === 'Movies';
    return Object.fromEntries(
      Object.entries({
        ...sharedFields,
        category: ticketCategory,
        date: String(formState.ticketDate || '').trim(),
        country: String(formState.ticketCountry || '').trim(),
        city: String(formState.ticketCity || '').trim(),
        location: String(formState.ticketLocation || '').trim(),
        provider: String(formState.ticketProvider || '').trim(),
        meta: String(formState.ticketMeta || '').trim(),
        genre: String(formState.ticketGenre || '').trim(),
        language: isMoviesCategory ? String(formState.ticketLanguage || '').trim() : '',
        showtime: isMoviesCategory ? String(formState.ticketShowtime || '').trim() : '',
      }).filter(([, value]) => Boolean(String(value || '').trim())),
    );
  }
  // Generic spec-driven payload for other markets.
  const spec = getMarketFieldSpec(formState.marketKey);
  if (spec) {
    const entries = spec.fields.map((field) => [field.name, String(formState[field.name] ?? '').trim()]);
    return Object.fromEntries(
      [...Object.entries(sharedFields), ...entries].filter(([, value]) => Boolean(String(value || '').trim())),
    );
  }
  return sharedFields;
};

// Build the persisted details_json for a seller listing, merging in any
// optional multi-size data (sizes / per-size stock / per-size price) on top
// of the market-specific fields so manual listings support packing sizes too.
const buildSellerItemDetailsJson = (formState) => ({
  ...buildSellerItemBaseDetailsJson(formState),
  ...buildSizeDetailFields(formState),
});

const getGroceriesListingMetaText = (item = {}) => {
  const categoryLabel = item.category || getGroceriesCategoryTitle(item.categoryKey);
  const parts = [categoryLabel, item.brand, item.volume, item.discount || item.freshness].filter(Boolean);

  return parts.join(' • ') || item.sellerName || 'Seller item';
};

const getGroceriesListingDetailsText = (item = {}) => {
  const categoryLabel = item.category || getGroceriesCategoryTitle(item.categoryKey);
  const parts = [
    item.discount,
    categoryLabel,
    item.brand,
    item.volume,
    item.freshness,
    item.storage ? `Storage: ${item.storage}` : '',
    item.origin ? `Origin: ${item.origin}` : '',
    item.expiryDate ? `Best before ${formatListingDateLabel(item.expiryDate)}` : '',
    item.description,
  ].filter(Boolean);

  return parts.join(' • ') || item.sellerName || 'Seller item';
};

const SALE_DISCOUNT_RATE = 0.2;

// Real seller listings carry an explicit `currency` and a `seller-` id, and
// must be shown and charged at exactly the price the seller set (currency
// converted only). The artificial "was/now" sale markdown is a demo device
// reserved for the static placeholder catalogue, which never carries a
// currency. Applying that markdown to a real listing under-prices it by
// SALE_DISCOUNT_RATE and makes the buyer-facing price differ from what the
// seller entered — the cause of price inconsistencies across every market.
const isSellerListingItem = (item) => Boolean(
  item && (item.currency || String(item.id || '').startsWith('seller-')),
);
const getItemSaleDiscountRate = (item) => (isSellerListingItem(item) ? 0 : SALE_DISCOUNT_RATE);

const formatSaleAmount = (amount, decimals) => new Intl.NumberFormat('en-US', {
  minimumFractionDigits: decimals,
  maximumFractionDigits: decimals,
}).format(amount);

