const FX_CACHE_KEY = 'svs-fx-rates';
const FX_TTL_MS = 6 * 60 * 60 * 1000; // 6 hours
const BUYER_CURRENCY_STORAGE_KEY = 'svs-buyer-currency';

const DEFAULT_BUYER_CURRENCY = 'ZAR';

const readInitialBuyerCurrency = () => {
  if (typeof window === 'undefined') return DEFAULT_BUYER_CURRENCY;
  const stored = window.localStorage.getItem(BUYER_CURRENCY_STORAGE_KEY);
  if (stored && SUPPORTED_CURRENCIES.some((entry) => entry.code === stored)) return stored;
  return DEFAULT_BUYER_CURRENCY;
};

const readCachedFxRates = () => {
  if (typeof window === 'undefined') return null;
  try {
    const raw = window.localStorage.getItem(FX_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object' || !parsed.rates) return null;
    return parsed;
  } catch (error) { return null; }
};

const _fxState = (() => {
  const cached = readCachedFxRates();
  return {
    rates: { ...FALLBACK_FX_RATES_USD, ...(cached?.rates || {}) },
    fetchedAt: cached?.fetchedAt || 0,
    buyerCurrency: readInitialBuyerCurrency(),
    inflightFetch: null,
  };
})();

const _fxSubscribers = new Set();
const notifyCurrencyChange = () => {
  _fxSubscribers.forEach((cb) => { try { cb(); } catch (error) { /* ignore */ } });
  // Notify feature modules (e.g. property) that read from localStorage so
  // same-tab currency switches propagate without a reload.
  if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
    try { window.dispatchEvent(new CustomEvent('svs-buyer-currency-change')); } catch (_e) { /* ignore */ }
  }
};

const setBuyerCurrency = (code) => {
  if (!SUPPORTED_CURRENCIES.some((entry) => entry.code === code)) return;
  if (_fxState.buyerCurrency === code) return;
  _fxState.buyerCurrency = code;
  if (typeof window !== 'undefined') {
    try { window.localStorage.setItem(BUYER_CURRENCY_STORAGE_KEY, code); } catch (error) { /* ignore */ }
  }
  notifyCurrencyChange();
};

const getCurrencyDefinition = (code) => SUPPORTED_CURRENCIES.find((entry) => entry.code === code) || SUPPORTED_CURRENCIES[0];

const refreshFxRates = async () => {
  if (typeof window === 'undefined') return;
  if (Date.now() - _fxState.fetchedAt < FX_TTL_MS && _fxState.fetchedAt > 0) return;
  if (_fxState.inflightFetch) return _fxState.inflightFetch;

  _fxState.inflightFetch = (async () => {
    try {
      const res = await fetch('https://open.er-api.com/v6/latest/USD');
      if (!res.ok) throw new Error('fx fetch failed');
      const data = await res.json();
      if (data && data.rates) {
        _fxState.rates = { ...FALLBACK_FX_RATES_USD, ...data.rates };
        _fxState.fetchedAt = Date.now();
        try {
          window.localStorage.setItem(FX_CACHE_KEY, JSON.stringify({ rates: _fxState.rates, fetchedAt: _fxState.fetchedAt }));
        } catch (error) { /* ignore */ }
        notifyCurrencyChange();
      }
    } catch (error) { /* keep fallback */ }
    finally { _fxState.inflightFetch = null; }
  })();

  return _fxState.inflightFetch;
};

const convertAmount = (amount, fromCode = 'USD', toCode = _fxState.buyerCurrency) => {
  const numericAmount = Number(amount) || 0;
  const fromRate = _fxState.rates[fromCode] || 1;
  const toRate = _fxState.rates[toCode] || 1;
  const usdValue = numericAmount / fromRate;
  return usdValue * toRate;
};

const formatAmountInCurrency = (amount, code = _fxState.buyerCurrency, decimals) => {
  const def = getCurrencyDefinition(code);
  const fixedDecimals = decimals != null ? decimals : (code === 'JPY' ? 0 : 2);
  const numericAmount = Number(amount) || 0;
  const symbol = def.symbol.length > 1 ? `${def.symbol} ` : def.symbol;
  return `${symbol}${formatSaleAmount(numericAmount, fixedDecimals)}`;
};

const detectCurrencyFromPriceString = (price) => {
  const text = String(price ?? '').trim();
  if (!text) return null;
  for (const sym of ['R$', 'C$', 'A$', 'GH₵', 'KSh', 'AED']) {
    if (text.startsWith(sym)) return SYMBOL_TO_CURRENCY[sym];
  }
  for (const sym of ['$', '€', '£', '₦', '₹', '¥']) {
    if (text.startsWith(sym)) return SYMBOL_TO_CURRENCY[sym];
  }
  if (/^R\s*\d/.test(text)) return 'ZAR';
  return null;
};

const useBuyerCurrency = () => {
  const [, setTick] = useState(0);
  useEffect(() => {
    const cb = () => setTick((n) => n + 1);
    _fxSubscribers.add(cb);
    refreshFxRates();
    // Re-check rates when the tab regains focus / becomes visible.
    const handleVisibility = () => {
      if (typeof document !== 'undefined' && document.visibilityState === 'visible') {
        refreshFxRates();
      }
    };
    // Periodic refresh (the call itself is a no-op if within TTL).
    const interval = setInterval(() => { refreshFxRates(); }, 30 * 60 * 1000);
    if (typeof document !== 'undefined') {
      document.addEventListener('visibilitychange', handleVisibility);
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('focus', handleVisibility);
    }
    return () => {
      _fxSubscribers.delete(cb);
      clearInterval(interval);
      if (typeof document !== 'undefined') {
        document.removeEventListener('visibilitychange', handleVisibility);
      }
      if (typeof window !== 'undefined') {
        window.removeEventListener('focus', handleVisibility);
      }
    };
  }, []);
  return {
    code: _fxState.buyerCurrency,
    setCode: setBuyerCurrency,
    rates: _fxState.rates,
    fetchedAt: _fxState.fetchedAt,
  };
};

const formatCheckoutAmount = (amount, fromCurrency = null) => {
  const buyerCode = _fxState.buyerCurrency;
  const sourceCode = fromCurrency || buyerCode;
  const converted = convertAmount(amount, sourceCode, buyerCode);
  return formatAmountInCurrency(converted, buyerCode, buyerCode === 'JPY' ? 0 : 2);
};

const getCartItemSourceCurrency = (item) => (
  item?.unitPriceCurrency
  || detectCurrencyFromPriceString(item?.unitPriceLabel || '')
  || _fxState.buyerCurrency
);

const formatCartItemAmount = (item, amount) => formatCheckoutAmount(amount, getCartItemSourceCurrency(item));

// Converts/formats a "rate card" style price string — e.g. "From 500 / hour"
// — which getSalePrices/SalePrice can't handle cleanly because their
// "preserve original formatting" path assumes any pre-existing prefix is
// itself a currency symbol, not free text like "From ". Splits out the
// leading text, the bare amount, and the trailing "/ unit" text, converts
// just the amount from sourceCurrency into the buyer's selected currency,
// and reassembles the surrounding text untouched.
const formatRateCardPrice = (text, sourceCurrency = 'ZAR') => {
  const raw = String(text ?? '');
  const match = raw.match(/^([^\d-]*)(\d[\d,]*(?:\.\d+)?)(.*)$/);
  if (!match) return raw;
  const [, prefix, amountText, suffix] = match;
  const amount = Number(amountText.replace(/,/g, ''));
  if (Number.isNaN(amount)) return raw;
  const buyerCurrency = _fxState.buyerCurrency;
  const converted = convertAmount(amount, sourceCurrency, buyerCurrency);
  return `${prefix}${formatAmountInCurrency(converted, buyerCurrency, buyerCurrency === 'JPY' ? 0 : 2)}${suffix}`;
};

const formatSellerAmount = (amount, sellerCurrency = 'USD', decimals) => formatAmountInCurrency(amount, sellerCurrency, decimals);


const getNumericPriceValue = (price, discountRate = SALE_DISCOUNT_RATE, sourceCurrency = null) => {
  const text = String(price ?? '').trim();
  const match = text.match(/^([^\d-]*)(\d[\d,]*(?:\.\d+)?)(.*)$/);

  if (!match) {
    return 0;
  }

  const amount = Number(match[2].replace(/,/g, ''));

  if (Number.isNaN(amount)) {
    return 0;
  }

  const fromCurrency = sourceCurrency || detectCurrencyFromPriceString(text) || 'USD';
  const buyerCurrency = _fxState.buyerCurrency;
  const convertedAmount = convertAmount(amount, fromCurrency, buyerCurrency);

  return Math.max(convertedAmount * (1 - discountRate), 0);
};

const normalizePriceFilterInput = (value) => String(value || '')
  .replace(/[^\d.]/g, '')
  .replace(/(\..*)\./g, '$1');

const parsePriceFilterInput = (value) => {
  const normalizedValue = normalizePriceFilterInput(value);

  if (!normalizedValue) {
    return null;
  }

  const parsedValue = Number(normalizedValue);
  return Number.isFinite(parsedValue) ? parsedValue : null;
};

const formatPriceFilterAmount = (amount, currencyCode = null) => {
  const safeAmount = Number(amount) || 0;
  const code = currencyCode || _fxState.buyerCurrency;
  const decimals = code === 'JPY' ? 0 : (Number.isInteger(safeAmount) ? 0 : 2);
  return formatAmountInCurrency(safeAmount, code, decimals);
};

const getPriceFilterStep = (minPrice, maxPrice) => {
  const priceSpread = Math.max((Number(maxPrice) || 0) - (Number(minPrice) || 0), 0);

  if (priceSpread <= 10) {
    return 0.5;
  }

  if (priceSpread <= 100) {
    return 1;
  }

  if (priceSpread <= 1000) {
    return 10;
  }

  return 50;
};

const useListingFocusFromQuery = (items, openHandler) => {
  const location = useLocation();
  const handledRef = useRef(null);

  useEffect(() => {
    const focusKey = new URLSearchParams(location.search).get('focus');
    if (!focusKey || !openHandler || handledRef.current === focusKey) return;
    const match = (items || []).find((candidate) => (
      String(candidate?.id) === focusKey || String(candidate?.sku) === focusKey
    ));
    if (!match) return;
    handledRef.current = focusKey;
    if (typeof window !== 'undefined') {
      window.requestAnimationFrame(() => {
        const target = document.getElementById(`listing-${match.id}`);
        if (target) target.scrollIntoView({ behavior: 'smooth', block: 'center' });
        openHandler(match);
      });
    }
  }, [location.search, items, openHandler]);
};

const useMarketplacePriceFilter = (items = [], boundsItems = null) => {
  const { code: buyerCurrencyCode } = useBuyerCurrency();
  const [isPriceFilterOpen, setIsPriceFilterOpen] = useState(false);
  const [minPriceInput, setMinPriceInput] = useState('');
  const [maxPriceInput, setMaxPriceInput] = useState('');

  const sourceForBounds = Array.isArray(boundsItems) && boundsItems.length ? boundsItems : items;
  const availablePrices = useMemo(() => sourceForBounds
    .map((item) => getNumericPriceValue(item?.price, getItemSaleDiscountRate(item), item?.currency || null))
    // eslint-disable-next-line react-hooks/exhaustive-deps
    .filter((price) => Number.isFinite(price) && price >= 0), [sourceForBounds, buyerCurrencyCode]);
  const minimumAvailablePrice = availablePrices.length ? Math.min(...availablePrices) : 0;
  const maximumAvailablePrice = availablePrices.length ? Math.max(...availablePrices) : 0;
  const sliderStep = useMemo(
    () => getPriceFilterStep(minimumAvailablePrice, maximumAvailablePrice),
    [maximumAvailablePrice, minimumAvailablePrice],
  );

  const normalizedBounds = useMemo(() => {
    const parsedMin = parsePriceFilterInput(minPriceInput);
    const parsedMax = parsePriceFilterInput(maxPriceInput);

    if (parsedMin !== null && parsedMax !== null && parsedMin > parsedMax) {
      return { minimumPrice: parsedMax, maximumPrice: parsedMin };
    }

    return { minimumPrice: parsedMin, maximumPrice: parsedMax };
  }, [maxPriceInput, minPriceInput]);

  const filteredItems = useMemo(() => items.filter((item) => {
    const numericPrice = getNumericPriceValue(item?.price, getItemSaleDiscountRate(item), item?.currency || null);

    if (normalizedBounds.minimumPrice !== null && numericPrice < normalizedBounds.minimumPrice) {
      return false;
    }

    if (normalizedBounds.maximumPrice !== null && numericPrice > normalizedBounds.maximumPrice) {
      return false;
    }

    return true;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [items, normalizedBounds, buyerCurrencyCode]);

  useEffect(() => {
    // When buyer currency changes, clear the manual min/max so bounds re-derive in the new currency.
    setMinPriceInput('');
    setMaxPriceInput('');
  }, [buyerCurrencyCode]);

  useEffect(() => {
    if (!availablePrices.length) {
      if (minPriceInput !== '' || maxPriceInput !== '') {
        setMinPriceInput('');
        setMaxPriceInput('');
      }

      return;
    }

    const parsedMin = parsePriceFilterInput(minPriceInput);
    const parsedMax = parsePriceFilterInput(maxPriceInput);
    const clampedMin = parsedMin === null
      ? null
      : Math.min(Math.max(parsedMin, minimumAvailablePrice), maximumAvailablePrice);
    const clampedMax = parsedMax === null
      ? null
      : Math.min(Math.max(parsedMax, minimumAvailablePrice), maximumAvailablePrice);
    const normalizedMin = clampedMin === null ? '' : String(Math.min(clampedMin, clampedMax ?? clampedMin));
    const normalizedMax = clampedMax === null ? '' : String(Math.max(clampedMax, clampedMin ?? clampedMax));

    if (normalizedMin !== minPriceInput) {
      setMinPriceInput(normalizedMin);
    }

    if (normalizedMax !== maxPriceInput) {
      setMaxPriceInput(normalizedMax);
    }
  }, [availablePrices.length, maximumAvailablePrice, maxPriceInput, minPriceInput, minimumAvailablePrice]);

  const hasActivePriceFilter = minPriceInput !== '' || maxPriceInput !== '';
  const sliderMinValue = normalizedBounds.minimumPrice ?? minimumAvailablePrice;
  const sliderMaxValue = normalizedBounds.maximumPrice ?? maximumAvailablePrice;

  const handleMinPriceChange = useCallback((value) => {
    setMinPriceInput(normalizePriceFilterInput(value));
  }, []);

  const handleMaxPriceChange = useCallback((value) => {
    setMaxPriceInput(normalizePriceFilterInput(value));
  }, []);

  const handleClearPriceFilter = useCallback(() => {
    setMinPriceInput('');
    setMaxPriceInput('');
  }, []);

  const handleSliderMinimumChange = useCallback((value) => {
    const nextMinimum = Math.min(Number(value) || minimumAvailablePrice, sliderMaxValue);
    setMinPriceInput(String(nextMinimum));
  }, [minimumAvailablePrice, sliderMaxValue]);

  const handleSliderMaximumChange = useCallback((value) => {
    const nextMaximum = Math.max(Number(value) || maximumAvailablePrice, sliderMinValue);
    setMaxPriceInput(String(nextMaximum));
  }, [maximumAvailablePrice, sliderMinValue]);

  return {
    filteredItems,
    hasActivePriceFilter,
    isPriceFilterOpen,
    minPriceInput,
    maxPriceInput,
    minimumAvailablePrice,
    maximumAvailablePrice,
    sliderMinValue,
    sliderMaxValue,
    sliderStep,
    setIsPriceFilterOpen,
    handleMinPriceChange,
    handleMaxPriceChange,
    handleClearPriceFilter,
    handleSliderMinimumChange,
    handleSliderMaximumChange,
  };
};

const getCartCount = (cartItems) => cartItems.reduce((total, item) => total + item.quantity, 0);
const getCartSubtotal = (cartItems) => cartItems.reduce((total, item) => {
  const fromCurrency = getCartItemSourceCurrency(item);
  const lineTotal = (Number(item.unitPrice) || 0) * (Number(item.quantity) || 0);
  return total + convertAmount(lineTotal, fromCurrency, _fxState.buyerCurrency);
}, 0);
