const syncUserCollection = async ({ tableName, userEmail, records, removeMissing = true }) => {
  if (!records.length) {
    if (!removeMissing) {
      return null;
    }

    const { error: clearError } = await supabase.from(tableName).delete().eq('user_email', userEmail);
    return clearError || null;
  }

  const { error: upsertError } = await supabase
    .from(tableName)
    .upsert(records, { onConflict: 'user_email,item_key' });

  if (upsertError) {
    return upsertError;
  }

  if (!removeMissing) {
    return null;
  }

  const { data: existingRows, error: fetchError } = await supabase
    .from(tableName)
    .select('item_key')
    .eq('user_email', userEmail);

  if (fetchError) {
    return fetchError;
  }

  const nextItemKeys = new Set(records.map((record) => record.item_key));
  const keysToDelete = (existingRows || [])
    .map((row) => row.item_key)
    .filter((itemKey) => !nextItemKeys.has(itemKey));

  if (!keysToDelete.length) {
    return null;
  }

  const { error: deleteError } = await supabase
    .from(tableName)
    .delete()
    .eq('user_email', userEmail)
    .in('item_key', keysToDelete);

  return deleteError || null;
};

const getStatusClasses = (status) => {
  switch (normalizeOrderStatus(status)) {
    case 'Delivered':
      return 'border-emerald-200 bg-emerald-50 text-emerald-700';
    case 'Out for Delivery':
      return 'border-teal-200 bg-teal-50 text-teal-700';
    case 'In Transit':
      return 'border-cyan-200 bg-cyan-50 text-cyan-700';
    case 'Package Shipped':
      return 'border-indigo-200 bg-indigo-50 text-indigo-700';
    case 'Order Processing':
      return 'border-blue-200 bg-blue-50 text-blue-700';
    case 'Order Confirmed':
      return 'border-violet-200 bg-violet-50 text-violet-700';
    case 'Cancelled by Buyer':
      return 'border-rose-200 bg-rose-50 text-rose-700';
    case 'Refund Pending':
      return 'border-orange-200 bg-orange-50 text-orange-700';
    case 'Refund Made':
      return 'border-emerald-200 bg-emerald-50 text-emerald-700';
    default:
      return 'border-slate-200 bg-slate-100 text-slate-700';
  }
};

const mapSellerItemRecord = (record) => {
  const marketConfig = sellerMarketConfig[record.market_key] || sellerMarketOptions[0];
  const imageList = Array.isArray(record.image_urls)
    ? record.image_urls.filter((url) => typeof url === 'string' && url.trim())
    : [];
  const primaryImage = record.image_url || imageList[0] || '';
  const rawDetailsJson = record.details_json && typeof record.details_json === 'object' && !Array.isArray(record.details_json)
    ? record.details_json
    : {};
  const resolvedSellerName = getSellerDisplayName({
    sellerName: record.seller_name,
    sellerEmail: record.seller_email,
    businessName: rawDetailsJson.businessName || rawDetailsJson.storeName || rawDetailsJson.shopName || rawDetailsJson.outletName,
    providerName: rawDetailsJson.provider,
  });
  const resolvedCategoryKey = String(rawDetailsJson.categoryKey || '').trim()
    || (record.market_key === 'groceries'
      ? resolveGroceriesCategoryKey({
        categoryKey: rawDetailsJson.categoryKey,
        category: rawDetailsJson.category,
        title: record.title,
        description: record.description,
      })
      : record.market_key === 'secondhand'
        ? resolveSecondhandCategoryKey(rawDetailsJson.category)
        : '');
  const resolvedCategory = String(rawDetailsJson.category || '').trim()
    || (record.market_key === 'groceries' ? getGroceriesCategoryTitle(resolvedCategoryKey) : '');

  // For beverages
  const beverageCategory = String(rawDetailsJson.beverageCategory || '');
  const beverageType = String(rawDetailsJson.beverageType || '');

  const sellerCurrency = (() => {
    const stored = String(rawDetailsJson.currency || '').toUpperCase();
    if (SUPPORTED_CURRENCIES.some((entry) => entry.code === stored)) return stored;
    return detectCurrencyFromPriceString(record.price) || 'USD';
  })();

  return {
    id: `seller-${record.id}`,
    dbId: record.id,
    title: record.title,
    description: record.description || rawDetailsJson.description || '',
    availableQuantity: normalizeListingQuantity(record.quantity, 0),
    price: record.price,
    currency: sellerCurrency,
    image: primaryImage,
    images: imageList.length ? imageList : (primaryImage ? [primaryImage] : []),
    marketKey: record.market_key,
    route: marketConfig.route,
    sellerName: resolvedSellerName,
    sellerEmail: record.seller_email || '',
    // Spread spec-driven attributes first so the explicit fields below win
    // for groceries / beverages / tickets, but generic markets get every
    // attribute they captured (size, color, condition, fuel, year, model,
    // etc.) exposed as flat item properties for filter-matching parity
    // with static items on each market page.
    ...rawDetailsJson,
    category: resolvedCategory || String(rawDetailsJson.category || ''),
    categoryKey: resolvedCategoryKey,
    brand: String(rawDetailsJson.brand || ''),
    volume: String(rawDetailsJson.volume || ''),
    freshness: String(rawDetailsJson.freshness || ''),
    storage: String(rawDetailsJson.storage || ''),
    origin: String(rawDetailsJson.origin || ''),
    expiryDate: String(rawDetailsJson.expiryDate || ''),
    discount: String(rawDetailsJson.discount || ''),
    subtitle: String(rawDetailsJson.subtitle || ''),
    meta: String(rawDetailsJson.meta || ''),
    provider: String(rawDetailsJson.provider || ''),
    location: String(rawDetailsJson.location || ''),
    country: String(rawDetailsJson.country || ''),
    date: String(rawDetailsJson.date || ''),
    city: String(rawDetailsJson.city || ''),
    genre: String(rawDetailsJson.genre || ''),
    language: String(rawDetailsJson.language || ''),
    showtime: String(rawDetailsJson.showtime || ''),
    attributes: rawDetailsJson,
    createdAt: record.created_at,
    isPaused: Boolean(record.is_paused),
    // Beverages
    beverageCategory,
    beverageType,
  };
};

const doesLineItemBelongToSeller = (lineItem, sellerEmail, ownedListingIds) => {
  const normalizedSellerEmail = normalizeEmail(sellerEmail);
  const lineSellerEmail = normalizeEmail(lineItem?.sellerEmail || '');

  if (normalizedSellerEmail && lineSellerEmail === normalizedSellerEmail) {
    return true;
  }

  const sku = String(lineItem?.sku || '');
  if (ownedListingIds.has(sku)) {
    return true;
  }

  const lineId = String(lineItem?.id || '');
  const rawId = lineId.includes(':') ? lineId.split(':').pop() : lineId;

  return ownedListingIds.has(rawId) || ownedListingIds.has(`seller-${rawId}`);
};

const getSellerItemsForMarket = (items, marketKey) => items.filter((item) => item.marketKey === marketKey && !item.isPaused);

const getSalePrices = (price, discountRate = SALE_DISCOUNT_RATE, sourceCurrency = null) => {
  const text = String(price ?? '').trim();
  const match = text.match(/^([^\d-]*)(\d[\d,]*(?:\.\d+)?)(.*)$/);

  if (!match) {
    return { wasPrice: text, nowPrice: text };
  }

  const [, prefix, amountText, suffix] = match;
  const normalizedAmountText = amountText.replace(/,/g, '');
  const amount = Number(normalizedAmountText);

  if (Number.isNaN(amount)) {
    return { wasPrice: text, nowPrice: text };
  }

  const detectedCurrency = sourceCurrency || detectCurrencyFromPriceString(text) || 'USD';
  const buyerCurrency = _fxState.buyerCurrency;
  const buyerDef = getCurrencyDefinition(buyerCurrency);

  const wasInBuyer = convertAmount(amount, detectedCurrency, buyerCurrency);
  const discountedInBuyer = Math.max(wasInBuyer * (1 - discountRate), 0);

  const decimals = buyerCurrency === 'JPY'
    ? 0
    : (normalizedAmountText.includes('.') ? Math.max(2, normalizedAmountText.split('.')[1].length) : 2);

  const symbol = buyerDef.symbol.length > 1 ? `${buyerDef.symbol} ` : buyerDef.symbol;

  // If buyer kept original currency, preserve original prefix/suffix; otherwise replace with new symbol.
  const useOriginalFormatting = detectedCurrency === buyerCurrency && (prefix || suffix);
  const formattedWas = useOriginalFormatting
    ? `${prefix}${formatSaleAmount(amount, decimals)}${suffix}`
    : `${symbol}${formatSaleAmount(wasInBuyer, decimals)}`;
  const formattedNow = useOriginalFormatting
    ? `${prefix}${formatSaleAmount(amount * (1 - discountRate), decimals)}${suffix}`
    : `${symbol}${formatSaleAmount(discountedInBuyer, decimals)}`;

  return { wasPrice: formattedWas, nowPrice: formattedNow };
};

const SalePrice = ({ price, currency = null, className = '', wasClassName = '', nowClassName = '' }) => {
  const { t } = useTranslation();
  useBuyerCurrency();
  // A provided currency marks a real seller listing, which is shown at exactly
  // the price the seller set (currency converted only) with no artificial
  // "was/now" markdown. Static demo items carry no currency and keep the sale.
  const isRealListing = Boolean(currency);
  const discountRate = isRealListing ? 0 : SALE_DISCOUNT_RATE;
  const { wasPrice, nowPrice } = getSalePrices(price, discountRate, currency);

  if (isRealListing) {
    return (
      <span className={`inline-flex items-center gap-2 ${className}`.trim()}>
        <span className={`font-bold text-[var(--svs-primary-strong)] ${nowClassName}`.trim()}>
          {nowPrice}
        </span>
      </span>
    );
  }

  return (
    <span className={`inline-flex items-center gap-2 ${className}`.trim()}>
      <span className={`text-xs text-slate-500 line-through ${wasClassName}`.trim()}>
        {t('pricing.was', { price: wasPrice })}
      </span>
      <span className={`font-bold text-[var(--svs-primary-strong)] ${nowClassName}`.trim()}>
        {t('pricing.now', { price: nowPrice })}
      </span>
    </span>
  );
};

const PriceFilterPanel = ({
  filteredCount,
  totalCount,
  isPriceFilterOpen,
  onToggleOpen,
  minPriceInput,
  maxPriceInput,
  onMinPriceChange,
  onMaxPriceChange,
  onClearPriceFilter,
  hasActivePriceFilter,
  minimumAvailablePrice,
  maximumAvailablePrice,
  sliderMinValue,
  sliderMaxValue,
  sliderStep,
  onSliderMinimumChange,
  onSliderMaximumChange,
}) => {
  const sliderTrackStart = maximumAvailablePrice > minimumAvailablePrice
    ? ((Math.min(sliderMinValue, sliderMaxValue) - minimumAvailablePrice) / (maximumAvailablePrice - minimumAvailablePrice)) * 100
    : 0;
  const sliderTrackEnd = maximumAvailablePrice > minimumAvailablePrice
    ? ((Math.max(sliderMinValue, sliderMaxValue) - minimumAvailablePrice) / (maximumAvailablePrice - minimumAvailablePrice)) * 100
    : 100;

  return (
    <section className="mb-3 rounded-lg border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2.5 sm:px-4 sm:py-3">
      <div className="flex flex-wrap items-center justify-between gap-2.5">
        <div className="min-w-0 flex-1">
          <p className="text-[11px] font-bold uppercase tracking-[0.14em] text-[var(--svs-primary-strong)]">Price filter</p>
          <p className="mt-0.5 text-xs text-[var(--svs-muted)] sm:text-sm">
            Showing {filteredCount} of {totalCount} items
            {totalCount ? ` • Range ${formatPriceFilterAmount(minimumAvailablePrice)} to ${formatPriceFilterAmount(maximumAvailablePrice)}` : ''}
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {hasActivePriceFilter ? (
            <button
              type="button"
              onClick={onClearPriceFilter}
              className="rounded-full border border-[var(--svs-border)] bg-white px-3 py-1.5 text-xs font-semibold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)] hover:text-[var(--svs-primary)] sm:text-sm"
            >
              Clear
            </button>
          ) : null}
          <button
            type="button"
            onClick={onToggleOpen}
            className="inline-flex items-center gap-2 rounded-full bg-[var(--svs-primary)] px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-[var(--svs-primary-strong)] sm:text-sm"
            aria-expanded={isPriceFilterOpen}
          >
            {isPriceFilterOpen ? 'Hide filter' : 'Filter prices'}
            <ChevronDown className={`h-4 w-4 transition ${isPriceFilterOpen ? 'rotate-180' : ''}`} />
          </button>
        </div>
      </div>
      {isPriceFilterOpen ? (
        <div className="mt-2.5 space-y-2.5 border-t border-[var(--svs-border)] pt-2.5">
          <div className="grid gap-3 lg:items-start">
            <div className="w-full space-y-2.5" role="group" aria-label="Price range slider">
              <div className="flex justify-start">
                <span className="inline-flex items-center gap-2 rounded-full bg-[var(--svs-surface-soft)] px-2 py-1 text-[11px] font-semibold text-[var(--svs-text)] sm:text-xs">
                  <span className="text-[var(--svs-muted)]">Selected range:</span>
                  <span>{formatPriceFilterAmount(Math.min(sliderMinValue, sliderMaxValue))} - {formatPriceFilterAmount(Math.max(sliderMinValue, sliderMaxValue))}</span>
                </span>
              </div>
              <div className="relative px-1 py-2">
                <div className="h-2.5 rounded-full bg-[var(--svs-border)]" />
                <div
                  className="pointer-events-none absolute top-2 h-2.5 rounded-full bg-[var(--svs-primary)]"
                  style={{ left: `${sliderTrackStart}%`, width: `${Math.max(sliderTrackEnd - sliderTrackStart, 0)}%` }}
                  aria-hidden="true"
                />
                <input
                  type="range"
                  min={minimumAvailablePrice}
                  max={maximumAvailablePrice}
                  step={sliderStep}
                  value={Math.min(sliderMinValue, sliderMaxValue)}
                  onChange={(event) => onSliderMinimumChange(event.target.value)}
                  className="svs-range-slider svs-range-slider-min pointer-events-auto absolute inset-x-0 top-0 h-6 w-full cursor-pointer bg-transparent"
                  aria-label="Minimum price slider"
                />
                <input
                  type="range"
                  min={minimumAvailablePrice}
                  max={maximumAvailablePrice}
                  step={sliderStep}
                  value={Math.max(sliderMinValue, sliderMaxValue)}
                  onChange={(event) => onSliderMaximumChange(event.target.value)}
                  className="svs-range-slider svs-range-slider-max pointer-events-auto absolute inset-x-0 top-0 h-6 w-full cursor-pointer bg-transparent"
                  aria-label="Maximum price slider"
                />
              </div>
              <div className="flex items-center justify-between text-[11px] text-[var(--svs-muted)] sm:text-xs">
                <span>{formatPriceFilterAmount(minimumAvailablePrice)}</span>
                <span>{formatPriceFilterAmount(maximumAvailablePrice)}</span>
              </div>
            </div>
          </div>
          <div className="text-[11px] text-[var(--svs-muted)] sm:text-xs">
            Drag the slider to narrow the price range.
            </div>
        </div>
      ) : null}
    </section>
  );
};

const CurrencySelectorButton = ({ compact = false, className = '' }) => {
  const { code, setCode, fetchedAt } = useBuyerCurrency();
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef(null);
  const activeDef = getCurrencyDefinition(code);

  useEffect(() => {
    if (!isOpen) return undefined;
    const handlePointerDown = (event) => {
      if (!wrapperRef.current?.contains(event.target)) setIsOpen(false);
    };
    window.addEventListener('mousedown', handlePointerDown);
    window.addEventListener('touchstart', handlePointerDown);
    return () => {
      window.removeEventListener('mousedown', handlePointerDown);
      window.removeEventListener('touchstart', handlePointerDown);
    };
  }, [isOpen]);

  const normalizedSearch = search.trim().toLowerCase();
  const filtered = normalizedSearch
    ? SUPPORTED_CURRENCIES.filter((entry) => (
      entry.code.toLowerCase().includes(normalizedSearch)
      || entry.name.toLowerCase().includes(normalizedSearch)
    ))
    : SUPPORTED_CURRENCIES;

  return (
    <div ref={wrapperRef} className={`relative ${className}`.trim()}>
      <button
        type="button"
        onClick={() => setIsOpen((prev) => !prev)}
        className={`inline-flex items-center gap-2 rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] px-3 ${compact ? 'py-1.5' : 'py-2'} text-sm font-semibold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)]`}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        aria-label="Display currency"
      >
        <span aria-hidden="true">{activeDef.flag}</span>
        <span>{activeDef.code}</span>
        <ChevronDown className={`h-4 w-4 transition ${isOpen ? 'rotate-180' : ''}`} />
      </button>
      {isOpen ? (
        <div className="absolute right-0 top-[calc(100%+8px)] z-[80] w-72 rounded-2xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-2 shadow-2xl">
          <div className="flex items-center gap-2 border-b border-[var(--svs-border)] px-2 pb-2">
            <Search className="h-4 w-4 text-[var(--svs-muted)]" />
            <input
              type="search"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search currencies..."
              className="w-full bg-transparent text-sm text-[var(--svs-text)] outline-none"
              aria-label="Search currencies"
            />
          </div>
          <ul className="max-h-72 overflow-y-auto py-1" role="menu">
            {filtered.map((entry) => {
              const isActive = entry.code === code;
              return (
                <li key={entry.code}>
                  <button
                    type="button"
                    onClick={() => {
                      setCode(entry.code);
                      setIsOpen(false);
                      setSearch('');
                    }}
                    className={`flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm transition ${isActive ? 'bg-[var(--svs-primary)] text-white' : 'text-[var(--svs-text)] hover:bg-[var(--svs-surface-soft)]'}`}
                    role="menuitemradio"
                    aria-checked={isActive}
                  >
                    <span className="text-base" aria-hidden="true">{entry.flag}</span>
                    <span className="font-bold">{entry.code}</span>
                    <span className={`flex-1 text-xs ${isActive ? 'text-white/85' : 'text-[var(--svs-muted)]'}`}>{entry.name}</span>
                    <span className={`text-xs font-semibold ${isActive ? 'text-white' : 'text-[var(--svs-muted)]'}`}>{entry.symbol}</span>
                  </button>
                </li>
              );
            })}
            {filtered.length === 0 ? (
              <li className="px-3 py-2 text-xs text-[var(--svs-muted)]">No currencies match.</li>
            ) : null}
          </ul>
          <p className="mt-1 border-t border-[var(--svs-border)] px-3 pt-2 text-[10px] text-[var(--svs-muted)]">
            <span className="inline-flex items-center gap-1">
              <span className="inline-block h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
              {fetchedAt ? `Live rates · updated ${new Date(fetchedAt).toLocaleTimeString()}` : 'Live rates loading…'}
            </span>
            <br />Sellers always paid in their listed currency.
          </p>
        </div>
      ) : null}
    </div>
  );
};

