const AddressAutocompleteField = ({
  label,
  value,
  onChange,
  onSelectAddress,
  inputClassName,
  placeholder = 'Start typing a street number, area, or suburb',
}) => {
  const [suggestions, setSuggestions] = useState([]);
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isApplyingSelection, setIsApplyingSelection] = useState(false);
  const [lookupError, setLookupError] = useState('');
  const [hasSearched, setHasSearched] = useState(false);
  const containerRef = useRef(null);
  const suppressLookupRef = useRef(false);
  const sessionTokenRef = useRef(createAddressLookupSessionToken());

  useEffect(() => {
    const query = String(value || '').trim();

    if (suppressLookupRef.current) {
      suppressLookupRef.current = false;
      return undefined;
    }

    if (query.length < 3) {
      setSuggestions([]);
      setIsOpen(false);
      setLookupError('');
      setIsLoading(false);
      setHasSearched(false);
      return undefined;
    }

    let cancelled = false;
    setIsLoading(true);

    const attemptLookup = async (attempt) => {
      try {
        const nextSuggestions = await lookupAddressSuggestions({
          input: query,
          sessionToken: sessionTokenRef.current,
          countryCode: 'za',
        });
        if (cancelled) return;
        setSuggestions(nextSuggestions);
        setIsOpen(true);
        setLookupError('');
        setHasSearched(true);
      } catch (error) {
        if (cancelled) return;
        if (attempt < 1) {
          // Single silent retry for transient failures (rate limit / proxy hiccup).
          window.setTimeout(() => {
            if (!cancelled) attemptLookup(attempt + 1);
          }, 600);
          return;
        }
        setSuggestions([]);
        setIsOpen(false);
        setHasSearched(true);
        setLookupError("We couldn't reach the address service. You can type your address manually below.");
      } finally {
        if (!cancelled && attempt >= 1) {
          setIsLoading(false);
        } else if (!cancelled) {
          // success path resolves loading here too
          setIsLoading(false);
        }
      }
    };

    const timeoutId = window.setTimeout(() => {
      attemptLookup(0);
    }, 280);

    return () => {
      cancelled = true;
      window.clearTimeout(timeoutId);
    };
  }, [value]);

  useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const handlePointerDown = (event) => {
      if (!containerRef.current?.contains(event.target)) {
        setIsOpen(false);
      }
    };

    window.addEventListener('mousedown', handlePointerDown);
    window.addEventListener('touchstart', handlePointerDown);

    return () => {
      window.removeEventListener('mousedown', handlePointerDown);
      window.removeEventListener('touchstart', handlePointerDown);
    };
  }, [isOpen]);

  const handleSelectSuggestion = async (suggestion) => {
    setIsApplyingSelection(true);
    setLookupError('');

    try {
      const details = await lookupAddressDetails({
        placeId: suggestion.placeId,
        sessionToken: sessionTokenRef.current,
      });

      suppressLookupRef.current = true;
      onSelectAddress(details);
      setSuggestions([]);
      setIsOpen(false);
      sessionTokenRef.current = createAddressLookupSessionToken();
    } catch (error) {
      setLookupError(error instanceof Error ? error.message : 'Unable to apply the selected address.');
    } finally {
      setIsApplyingSelection(false);
    }
  };

  return (
    <div className="relative" ref={containerRef}>
      <span className="mb-2 block text-sm font-medium text-[var(--svs-text)]">{label}</span>
      <label className="relative block">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[var(--svs-muted)]" />
        <input
          type="text"
          value={value}
          onChange={(event) => onChange(event.target.value)}
          placeholder={placeholder}
          className={`${inputClassName} pl-10 pr-10`}
          autoComplete="street-address"
        />
        {isLoading || isApplyingSelection ? (
          <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-xs font-semibold text-[var(--svs-muted)]">
            {isApplyingSelection ? 'Filling...' : 'Searching...'}
          </span>
        ) : null}
      </label>
      <p className="mt-2 text-xs text-[var(--svs-muted)]">Search by street number, area, or suburb and select a result to fill the address fields.</p>
      {lookupError ? <p className="mt-2 text-xs font-medium text-[#d94d4d]">{lookupError}</p> : null}
      {isOpen ? (
        <div className="absolute left-0 right-0 top-[calc(100%+8px)] z-20 overflow-hidden rounded-2xl border border-[var(--svs-border)] bg-[var(--svs-surface)] shadow-2xl">
          <div className="max-h-72 overflow-y-auto p-2">
            {suggestions.length === 0 && hasSearched && !isLoading ? (
              <div className="px-3 py-4 text-center text-xs text-[var(--svs-muted)]">
                No matches found. Try adding the suburb or city, or type your address manually.
              </div>
            ) : null}
            {suggestions.map((suggestion) => (
              <button
                key={suggestion.placeId}
                type="button"
                onClick={() => {
                  void handleSelectSuggestion(suggestion);
                }}
                className="mb-1 flex w-full items-start gap-3 rounded-xl px-3 py-3 text-left transition hover:bg-[var(--svs-surface-soft)] last:mb-0"
              >
                <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-[var(--svs-primary)]" />
                <span className="min-w-0 flex-1">
                  <span className="block text-sm font-semibold text-[var(--svs-text)]">{suggestion.primaryText}</span>
                  <span className="mt-1 block text-xs text-[var(--svs-muted)]">
                    {suggestion.secondaryText || suggestion.fullText}
                  </span>
                </span>
              </button>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
};

// Searchable currency picker shown next to the seller's price input.
// Mirrors the look used on the property listing page (flag + code button
// that opens a searchable dropdown). The onChange callback receives a
// synthetic event ({ target: { name, value } }) so it can be plugged
// straight into the existing handleChange / handleEditChange handlers
// without any wrapper code.
const CurrencyPickerField = ({
  id,
  name = 'currency',
  value,
  onChange,
  ariaLabel = 'Listing currency',
  className = '',
}) => {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const rootRef = useRef(null);
  const searchRef = useRef(null);

  const selected = useMemo(() => (
    SUPPORTED_CURRENCIES.find((entry) => entry.code === value) || null
  ), [value]);

  useEffect(() => {
    if (!open) return undefined;
    const handleDocClick = (event) => {
      if (rootRef.current && !rootRef.current.contains(event.target)) setOpen(false);
    };
    const handleKey = (event) => {
      if (event.key === 'Escape') setOpen(false);
    };
    document.addEventListener('mousedown', handleDocClick);
    document.addEventListener('keydown', handleKey);
    const focusTimer = setTimeout(() => searchRef.current?.focus(), 30);
    return () => {
      document.removeEventListener('mousedown', handleDocClick);
      document.removeEventListener('keydown', handleKey);
      clearTimeout(focusTimer);
    };
  }, [open]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return SUPPORTED_CURRENCIES;
    return SUPPORTED_CURRENCIES.filter((entry) => (
      entry.code.toLowerCase().includes(q)
      || entry.name.toLowerCase().includes(q)
      || (entry.symbol || '').toLowerCase().includes(q)
    ));
  }, [query]);

  const selectCode = (code) => {
    setOpen(false);
    setQuery('');
    onChange?.({ target: { name, value: code } });
  };

  return (
    <div ref={rootRef} className={`relative ${className}`.trim()}>
      <button
        type="button"
        id={id}
        onClick={() => setOpen((prev) => !prev)}
        className="flex items-center gap-1.5 rounded-lg border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-2.5 py-2.5 text-sm text-[var(--svs-text)] outline-none focus:border-[var(--svs-primary)]"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-label={ariaLabel}
      >
        <span className="text-base leading-none">{selected?.flag || '�'}</span>
        <span className={`font-medium ${selected ? '' : 'text-[var(--svs-muted)]'}`}>{selected?.code || 'Select'}</span>
        <ChevronDown className="h-3.5 w-3.5 shrink-0 text-[var(--svs-muted)]" />
      </button>
      {open ? (
        <div className="absolute left-0 top-full z-40 mt-1 w-[280px] overflow-hidden rounded-lg border border-[var(--svs-border)] bg-[var(--svs-surface)] shadow-xl">
          <div className="flex items-center gap-2 border-b border-[var(--svs-border)] px-2 py-1.5">
            <Search className="h-3.5 w-3.5 text-[var(--svs-muted)]" />
            <input
              ref={searchRef}
              type="text"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search currency or country…"
              className="w-full bg-transparent text-sm text-[var(--svs-text)] outline-none"
            />
          </div>
          <ul role="listbox" className="max-h-64 overflow-y-auto py-1">
            {filtered.length === 0 ? (
              <li className="px-3 py-2 text-xs text-[var(--svs-muted)]">No matches</li>
            ) : (
              filtered.map((entry) => {
                const isSel = entry.code === selected?.code;
                return (
                  <li key={entry.code}>
                    <button
                      type="button"
                      onClick={() => selectCode(entry.code)}
                      className={`flex w-full items-center gap-2 px-3 py-2 text-left text-sm hover:bg-[var(--svs-surface-soft)] ${isSel ? 'bg-[var(--svs-cyan-surface)] font-semibold' : ''}`}
                    >
                      <span className="text-base leading-none">{entry.flag}</span>
                      <span className="w-14 font-medium text-[var(--svs-text)]">{entry.code}</span>
                      <span className="flex-1 truncate text-xs text-[var(--svs-muted)]">{entry.name}</span>
                      {isSel ? <Check className="h-3.5 w-3.5 text-[var(--svs-primary)]" /> : null}
                    </button>
                  </li>
                );
              })
            )}
          </ul>
        </div>
      ) : null}
    </div>
  );
};

const MarketSelectorField = ({
  id,
  value,
  onChange,
  placeholder = 'Select Market',
  ariaLabel = 'Market selector',
}) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef(null);
  const selectedOption = sellerMarketOptions.find((option) => option.key === value);

  useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const handlePointerDown = (event) => {
      if (!containerRef.current?.contains(event.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handlePointerDown);

    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
    };
  }, [isOpen]);

  return (
    <div className="relative" ref={containerRef}>
      <button
        id={id}
        type="button"
        onClick={() => setIsOpen((previous) => !previous)}
        className="inline-flex w-full items-center justify-between rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] px-3 py-2 text-sm font-semibold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)] focus:border-[var(--svs-primary)] focus:outline-none focus:ring-2 focus:ring-[#33b9f2]/40"
        aria-label={ariaLabel}
        aria-haspopup="menu"
        aria-expanded={isOpen}
      >
        <span>{selectedOption ? t(selectedOption.labelKey) : placeholder}</span>
        <ChevronDown className={`h-4 w-4 transition ${isOpen ? 'rotate-180' : ''}`} />
      </button>

      {isOpen ? (
        <div
          className="absolute left-0 top-[calc(100%+8px)] z-[70] w-full overflow-hidden rounded-2xl border border-[var(--svs-border)] bg-[var(--svs-surface)] shadow-2xl"
          role="menu"
          aria-label={ariaLabel}
        >
          <div className="max-h-72 overflow-y-auto p-2">
            {sellerMarketOptions.filter((option) => !option.hidden).map((option) => {
              const isSelected = option.key === value;

              return (
                <button
                  key={option.key}
                  type="button"
                  onClick={() => {
                    setIsOpen(false);
                    if (option.externalSellRoute) {
                      navigate(option.externalSellRoute);
                      return;
                    }
                    onChange(option.key);
                  }}
                  className={`mb-1 flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm transition last:mb-0 ${
                    isSelected
                      ? 'bg-[var(--svs-cyan-surface)] text-[var(--svs-primary-strong)]'
                      : 'text-[var(--svs-text)] hover:bg-[var(--svs-surface-soft)]'
                  }`}
                  aria-checked={isSelected}
                  role="menuitemradio"
                >
                  <span className="font-medium">{t(option.labelKey)}{option.externalSellRoute ? ' →' : ''}</span>
                  <span
                    className={`h-4 w-4 rounded-full border-2 ${
                      isSelected ? 'border-[var(--svs-primary)] bg-[var(--svs-primary)]' : 'border-[var(--svs-border)] bg-transparent'
                    }`}
                    aria-hidden="true"
                  />
                </button>
              );
            })}
          </div>
        </div>
      ) : null}
    </div>
  );
};

const Shell = ({ children, cartItemCount = 0, wishlistItemCount = 0, notifications = [], onMarkNotificationsRead, onMarkNotificationRead, onRemoveNotification, onClearNotifications, searchCatalog = [] }) => {
  const { t, i18n } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [isLanguageModalOpen, setIsLanguageModalOpen] = useState(false);
  const [pendingLanguageCode, setPendingLanguageCode] = useState(DEFAULT_LANGUAGE_CODE);
  const [focusedLanguageIndex, setFocusedLanguageIndex] = useState(0);
  const [languageSearchQuery, setLanguageSearchQuery] = useState('');
  const [query, setQuery] = useState('');
  const [remoteQuickSearchCatalog, setRemoteQuickSearchCatalog] = useState([]);
  const [isQuickSearchLoading, setIsQuickSearchLoading] = useState(false);
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const searchFormRef = useRef(null);
  const [isAuthenticated, setIsAuthenticated] = useState(getAuthState);
  const [hasSellerAccess, setHasSellerAccess] = useState(getSellerAccessState);
  const [sellerHomePath, setSellerHomePath] = useState(getSellerHomePath);
  const [profileOpen, setProfileOpen] = useState(false);
  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
  const notificationsPanelWasOpenRef = useRef(false);
  const [profileName, setProfileName] = useState('SVS User');
  const [theme, setTheme] = useState(getThemePreference);
  // Add default priceRange state to prevent ReferenceError
  const [priceRange] = useState([0, 20]);
  const languageCardRefs = useRef([]);
  const desktopLanguageMenuRef = useRef(null);
  const mobileLanguageMenuRef = useRef(null);
  const notificationsMenuRef = useRef(null);
  const isDarkMode = theme === 'dark';
  const isSellerConsoleRoute = location.pathname.startsWith('/seller/') || location.pathname === '/sell/onboarding';
  const activeLanguage = getLanguageByCode(i18n.resolvedLanguage || i18n.language);
  const popularSearchTerms = useMemo(() => [
    'Groceries',
    'Fast Food',
    'Beverages',
    'Fashion',
    'Electronics',
    'Property',
    'Vehicles',
    'Tickets',
    'Informal Market',
    'Wellness',
  ], []);
  const unreadNotificationsCount = useMemo(
    () => notifications.reduce((count, notification) => (notification.read ? count : count + 1), 0),
    [notifications],
  );
  const filteredLanguages = useMemo(() => {
    const normalizedQuery = languageSearchQuery.trim().toLowerCase();

    if (!normalizedQuery) {
      return SUPPORTED_LANGUAGES;
    }

    return SUPPORTED_LANGUAGES.filter((language) => {
      const haystack = [language.englishName, language.nativeName, language.code]
        .join(' ')
        .toLowerCase();

      return haystack.includes(normalizedQuery);
    });
  }, [languageSearchQuery]);

  const closeLanguageModal = () => {
    setLanguageSearchQuery('');
    setIsLanguageModalOpen(false);
  };

  const applyLanguageCode = useCallback(async (languageCode) => {
    const nextLanguage = getLanguageByCode(languageCode);
    await i18n.changeLanguage(nextLanguage.code);
    window.localStorage.setItem('svs-language', nextLanguage.code);

    if (isAuthenticated && hasSupabaseEnv && supabase) {
      const userEmail = window.localStorage.getItem('svs-user-email');
      if (userEmail) {
        await supabase
          .from('account_users')
          .update({ preferred_language: nextLanguage.code })
          .eq('email_address', userEmail);
      }
    }

    setIsLanguageModalOpen(false);
    if (typeof window !== 'undefined') window.location.reload();
  }, [i18n, isAuthenticated]);

  useEffect(() => {
    setIsAuthenticated(getAuthState());
    setHasSellerAccess(getSellerAccessState());
    setSellerHomePath(getSellerHomePath());
    setProfileOpen(false);
    setIsLanguageModalOpen(false);
    setIsNotificationsOpen(false);
  }, [location.pathname]);

  useEffect(() => {
    const handleAuthChange = () => {
      setIsAuthenticated(getAuthState());
      setHasSellerAccess(getSellerAccessState());
      setSellerHomePath(getSellerHomePath());
    };

    window.addEventListener('svs-auth-changed', handleAuthChange);

    return () => {
      window.removeEventListener('svs-auth-changed', handleAuthChange);
    };
  }, []);

  useEffect(() => {
    if (!isNotificationsOpen) {
      return undefined;
    }

    const handlePointerDown = (event) => {
      if (!notificationsMenuRef.current?.contains(event.target)) {
        setIsNotificationsOpen(false);
      }
    };

    window.addEventListener('mousedown', handlePointerDown);
    window.addEventListener('touchstart', handlePointerDown);

    return () => {
      window.removeEventListener('mousedown', handlePointerDown);
      window.removeEventListener('touchstart', handlePointerDown);
    };
  }, [isNotificationsOpen]);

  // Clear all remaining notifications when the panel closes so that every
  // notification the user has seen disappears once the panel is dismissed.
  useEffect(() => {
    if (notificationsPanelWasOpenRef.current && !isNotificationsOpen) {
      onClearNotifications?.();
    }
    notificationsPanelWasOpenRef.current = isNotificationsOpen;
  }, [isNotificationsOpen, onClearNotifications]);

  useEffect(() => {
    window.localStorage.setItem('svs-theme', theme);
  }, [theme]);

  useEffect(() => {
    const loadProfileName = async () => {
      if (!isAuthenticated) {
        setProfileName(t('profile.defaultName'));
        return;
      }

      const cachedName = window.localStorage.getItem('svs-user-name');
      const userEmail = window.localStorage.getItem('svs-user-email');

      if (cachedName) {
        setProfileName(cachedName);
      }

      if (!hasSupabaseEnv || !supabase || !userEmail) {
        return;
      }

      const { data, error } = await supabase
        .from('account_users')
        .select('full_name')
        .eq('email_address', userEmail)
        .maybeSingle();

      if (!error && data?.full_name) {
        setProfileName(data.full_name);
        window.localStorage.setItem('svs-user-name', data.full_name);
      }
    };

    loadProfileName();
  }, [isAuthenticated, t]);

  useEffect(() => {
    const currentLanguage = getLanguageByCode(i18n.resolvedLanguage || i18n.language);
    setPendingLanguageCode(currentLanguage.code);
    setFocusedLanguageIndex(SUPPORTED_LANGUAGES.findIndex((language) => language.code === currentLanguage.code));

    const nextDir = isRtlLanguage(currentLanguage.code) ? 'rtl' : 'ltr';
    document.documentElement.setAttribute('lang', currentLanguage.code);
    document.documentElement.setAttribute('dir', nextDir);
  }, [i18n.language, i18n.resolvedLanguage]);

  useEffect(() => {
    if (!isLanguageModalOpen) {
      return;
    }

    const selectedIndex = filteredLanguages.findIndex((language) => language.code === pendingLanguageCode);
    setFocusedLanguageIndex(selectedIndex >= 0 ? selectedIndex : 0);
    languageCardRefs.current = languageCardRefs.current.slice(0, filteredLanguages.length);
  }, [filteredLanguages, isLanguageModalOpen, pendingLanguageCode]);

  useEffect(() => {
    if (!isLanguageModalOpen) {
      return undefined;
    }

    const onKeyDown = (event) => {
      const maxIndex = filteredLanguages.length - 1;

      if (event.key === 'Escape') {
        event.preventDefault();
        closeLanguageModal();
        return;
      }

      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        if (!filteredLanguages.length) {
          return;
        }

        event.preventDefault();
        setFocusedLanguageIndex((currentIndex) => {
          const nextIndex = event.key === 'ArrowDown'
            ? (currentIndex >= maxIndex ? 0 : currentIndex + 1)
            : (currentIndex <= 0 ? maxIndex : currentIndex - 1);
          const nextLanguage = filteredLanguages[nextIndex];
          setPendingLanguageCode(nextLanguage.code);
          languageCardRefs.current[nextIndex]?.focus();
          languageCardRefs.current[nextIndex]?.scrollIntoView({ block: 'nearest' });
          return nextIndex;
        });
      }

      if (event.key === 'Enter') {
        if (!filteredLanguages.length) {
          return;
        }

        event.preventDefault();
        const selectedLanguage = filteredLanguages[focusedLanguageIndex] || getLanguageByCode(pendingLanguageCode);
        setPendingLanguageCode(selectedLanguage.code);
        applyLanguageCode(selectedLanguage.code);
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [applyLanguageCode, filteredLanguages, focusedLanguageIndex, isLanguageModalOpen, pendingLanguageCode]);

  useEffect(() => {
    if (!isLanguageModalOpen) {
      return undefined;
    }

    const handlePointerDown = (event) => {
      const desktopMenu = desktopLanguageMenuRef.current;
      const mobileMenu = mobileLanguageMenuRef.current;

      if (desktopMenu?.contains(event.target) || mobileMenu?.contains(event.target)) {
        return;
      }

      closeLanguageModal();
    };

    window.addEventListener('mousedown', handlePointerDown);
    window.addEventListener('touchstart', handlePointerDown);

    return () => {
      window.removeEventListener('mousedown', handlePointerDown);
      window.removeEventListener('touchstart', handlePointerDown);
    };
  }, [isLanguageModalOpen]);

  useEffect(() => {
    if (!isSearchFocused) {
      return undefined;
    }

    const handlePointerDown = (event) => {
      if (searchFormRef.current && !searchFormRef.current.contains(event.target)) {
        setIsSearchFocused(false);
      }
    };

    document.addEventListener('mousedown', handlePointerDown);
    document.addEventListener('touchstart', handlePointerDown);
    return () => {
      document.removeEventListener('mousedown', handlePointerDown);
      document.removeEventListener('touchstart', handlePointerDown);
    };
  }, [isSearchFocused]);

  const quickSearchSource = useMemo(
    () => dedupeSearchCatalogEntries([
      ...searchableCatalog,
      ...buildProjectWideStaticSearchCatalog(),
      ...(Array.isArray(searchCatalog) ? searchCatalog : []),
      ...remoteQuickSearchCatalog,
    ]),
    [remoteQuickSearchCatalog, searchCatalog],
  );

  useEffect(() => {
    const rawQuery = String(query || '').trim();

    if (!rawQuery || rawQuery.length < 2) {
      setRemoteQuickSearchCatalog([]);
      setIsQuickSearchLoading(false);
      return undefined;
    }

    const distilledQuery = distillQuery(rawQuery);
    const effectiveQuery = distilledQuery || rawQuery;
    let isCancelled = false;

    setIsQuickSearchLoading(true);
    const timeoutId = window.setTimeout(() => {
      fetchRemoteGlobalSearchEntries(effectiveQuery)
        .then((entries) => {
          if (isCancelled) return;
          setRemoteQuickSearchCatalog(entries || []);
        })
        .catch(() => {
          if (isCancelled) return;
          setRemoteQuickSearchCatalog([]);
        })
        .finally(() => {
          if (isCancelled) return;
          setIsQuickSearchLoading(false);
        });
    }, 280);

    return () => {
      isCancelled = true;
      window.clearTimeout(timeoutId);
    };
  }, [query]);

  const quickResults = useMemo(() => {
    const needle = query.trim();

    if (!needle) {
      return [];
    }

    const distilledNeedle = distillQuery(needle);
    const effectiveNeedle = distilledNeedle || needle;

    // Powerful cross-market search: multi-token AND, weighted field scoring,
    // diacritic-insensitive, with typo-tolerant fuzzy matching.
    return searchItemsPowerful(quickSearchSource, effectiveNeedle, {
      fields: [
        { key: 'title', weight: 10 },
        { key: 'subtitle', weight: 6 },
        { key: 'category', weight: 6 },
        { key: 'type', weight: 6 },
        { key: 'location', weight: 6 },
        { key: 'section', weight: 4 },
      ],
      haystackField: 'searchText',
      limit: 6,
    });
  }, [quickSearchSource, query]);

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    const term = query.trim();

    if (!term) {
      return;
    }

    navigate(`/search?query=${encodeURIComponent(term)}`);
    setQuery('');
    setMobileOpen(false);
    setIsSearchFocused(false);
    if (typeof document !== 'undefined' && document.activeElement instanceof HTMLElement) {
      document.activeElement.blur();
    }
  };

  const handleQuickSelect = (term) => {
    navigate(`/search?query=${encodeURIComponent(term)}`);
    setQuery('');
    setMobileOpen(false);
    setIsSearchFocused(false);
  };

  const handleCloseSearchSuggestions = () => {
    setQuery('');
    setIsSearchFocused(false);
    if (typeof document !== 'undefined' && document.activeElement instanceof HTMLElement) {
      document.activeElement.blur();
    }
  };

  const handleQuickResultSelect = (item) => {
    if (item?.route) {
      navigate(item.route);
      setQuery('');
      setMobileOpen(false);
      setIsSearchFocused(false);
      return;
    }

    const term = String(item?.title || '').trim();
    if (term) {
      handleQuickSelect(term);
    }
  };

  const handleLogout = () => {
    window.localStorage.removeItem('svs-authenticated');
    window.localStorage.removeItem('svs-user-email');
    window.localStorage.removeItem('svs-user-name');
    window.localStorage.removeItem(SELLER_ACCESS_STORAGE_KEY);
    window.localStorage.removeItem(SELLER_HOME_PATH_STORAGE_KEY);
    window.dispatchEvent(new Event('svs-auth-changed'));
    setIsAuthenticated(false);
    setHasSellerAccess(false);
    setSellerHomePath('/seller/dashboard');
    setProfileName(t('profile.defaultName'));
    setProfileOpen(false);
    navigate('/');
  };

  const toggleTheme = () => {
    setTheme((currentTheme) => (currentTheme === 'dark' ? 'light' : 'dark'));
  };

  return (
    <div className={`min-h-screen bg-[var(--svs-bg)] text-[var(--svs-text)] ${isDarkMode ? 'theme-dark' : 'theme-light'}`.trim()}>
      {/* Accessibility: keyboard users can jump straight to the page body */}
      <a
        href="#main-content"
        className="sr-only focus:not-sr-only focus:fixed focus:left-3 focus:top-3 focus:z-[100] focus:rounded-md focus:bg-[var(--svs-primary)] focus:px-3 focus:py-2 focus:text-sm focus:font-semibold focus:text-white focus:shadow-lg focus:outline-none focus:ring-2 focus:ring-white"
      >
        Skip to main content
      </a>
      <header className="fixed top-0 z-50 w-full border-b border-[var(--svs-border)] bg-[var(--svs-nav-bg)]/95 text-[var(--svs-nav-text)] backdrop-blur-md">
        <div className="mx-auto flex w-full max-w-7xl items-center gap-2 px-3 py-3 sm:gap-3 sm:px-4">
          <button
            type="button"
            onClick={() => setMobileOpen((prev) => !prev)}
            className="shrink-0 rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface)] p-2 text-[var(--svs-nav-text)] lg:hidden"
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X className="h-5 w-5" /> : <Menu className="h-5 w-5" />}
          </button>

          <nav className="hidden items-center gap-6 text-sm font-semibold text-[var(--svs-nav-text)] lg:flex">
            {isSellerConsoleRoute ? sellerConsoleNavItems.map((item) => (
              <Link key={item.href} to={item.href} className="transition hover:text-[var(--svs-primary)]">
                {item.label}
              </Link>
            )) : navItems.map((item) => (
              <Link key={item.labelKey} to={item.href} className="transition hover:text-[var(--svs-primary)]">
                {t(item.labelKey)}
              </Link>
            ))}
            {isSellerConsoleRoute ? (
              <Link
                to="/markets"
                className="ml-1 rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-1.5 text-xs font-bold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)] hover:text-[var(--svs-primary)]"
              >
                Switch to Buyer View
              </Link>
            ) : hasSellerAccess ? (
              <Link
                to={sellerHomePath}
                className="ml-1 rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-1.5 text-xs font-bold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)] hover:text-[var(--svs-primary)]"
              >
                Switch to Seller View
              </Link>
            ) : (
              <Link
                to="/sell"
                className="ml-1 rounded-full bg-orange-500 px-3 py-1.5 text-xs font-bold text-white transition hover:bg-orange-600"
              >
                Sell on SVS
              </Link>
            )}
          </nav>

          <form
            ref={searchFormRef}
            className={`relative max-w-xl flex-1 ${isSellerConsoleRoute ? 'hidden' : ''}`}
            onSubmit={handleSearchSubmit}
          >
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              inputMode="search"
              enterKeyHint="search"
              dir="auto"
              autoCorrect="off"
              autoCapitalize="none"
              spellCheck={false}
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onFocus={() => setIsSearchFocused(true)}
              placeholder={t('search.placeholder')}
              className="w-full rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] py-2 pl-9 pr-28 text-sm text-[var(--svs-text)] outline-none focus:border-[var(--svs-primary)] focus:ring-2 focus:ring-[#33b9f2]/40"
              aria-label={t('search.globalAria')}
            />
            <div className="absolute right-1.5 top-1/2 flex -translate-y-1/2 items-center gap-1">
              {query.trim() ? (
                <button
                  type="button"
                  onClick={() => {
                    setQuery('');
                    setIsSearchFocused(true);
                  }}
                  aria-label="Clear search"
                  className="inline-flex h-7 w-7 items-center justify-center rounded-full text-[var(--svs-muted)] transition hover:bg-[var(--svs-surface-soft)] hover:text-[var(--svs-primary-strong)]"
                >
                  <X className="h-4 w-4" />
                </button>
              ) : null}
              <button
                type="submit"
                className="inline-flex h-8 items-center gap-1.5 rounded-full bg-[var(--svs-primary)] px-3 text-xs font-bold text-white shadow-sm transition hover:bg-[var(--svs-primary-strong)]"
              >
                <Search className="h-3.5 w-3.5" />
                Search
              </button>
            </div>
            {isSearchFocused || query.trim() ? (
              <div className="fixed inset-x-2 top-[68px] z-[85] max-h-[80vh] overflow-y-auto rounded-2xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-3 shadow-2xl sm:absolute sm:inset-x-auto sm:left-0 sm:right-0 sm:top-[calc(100%+8px)] sm:max-h-none sm:w-auto sm:overflow-visible">
                <div className="mb-3 flex items-start justify-between gap-2 px-1">
                  <p className="flex flex-wrap items-center gap-1.5 text-[11px] text-[var(--svs-muted)]">
                    <Sparkles className="h-3.5 w-3.5 text-[var(--svs-primary)]" />
                    <span className="font-semibold text-[var(--svs-text)]">AI-assisted</span>
                    <span aria-hidden>•</span>
                    <span>Understands natural language</span>
                    <span aria-hidden>•</span>
                    <span>Searches our directory, the web, and AI engines</span>
                  </p>
                  <button
                    type="button"
                    onClick={handleCloseSearchSuggestions}
                    aria-label="Close search suggestions"
                    className="inline-flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-[var(--svs-muted)] transition hover:bg-[var(--svs-surface-soft)] hover:text-[var(--svs-primary-strong)]"
                  >
                    <X className="h-4 w-4" />
                  </button>
                </div>

                {!query.trim() ? (
                  <div className="rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] p-3">
                    <p className="mb-2 text-[11px] font-bold uppercase tracking-wide text-[var(--svs-muted)]">
                      Popular searches
                    </p>
                    <div className="flex flex-wrap gap-1.5">
                      {popularSearchTerms.map((term) => (
                        <button
                          key={`popular-${term}`}
                          type="button"
                          onClick={() => handleQuickSelect(term)}
                          className="rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] px-3 py-1 text-xs font-semibold text-[var(--svs-primary-strong)] transition hover:border-[var(--svs-primary)] hover:bg-[var(--svs-cyan-surface)]"
                        >
                          {term}
                        </button>
                      ))}
                    </div>
                    <p className="mt-3 text-[11px] text-[var(--svs-muted)]">
                      Start typing to search across our directory, the web, and AI engines.
                    </p>
                  </div>
                ) : (
                  <div className="max-h-[70vh] space-y-3 overflow-y-auto pr-1">
                    <section className="rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-3">
                      <header className="mb-2 flex items-center justify-between gap-2">
                        <p className="text-[11px] font-bold uppercase tracking-wide text-[var(--svs-muted)]">
                          From our directory
                        </p>
                        {isQuickSearchLoading ? (
                          <span className="text-[10px] text-[var(--svs-muted)]">Checking live database…</span>
                        ) : null}
                      </header>
                      {quickResults.length ? (
                        <ul className="space-y-1.5 text-sm text-[var(--svs-text)]">
                          {quickResults.map((item) => {
                            const itemTitle = getTranslatedValue(t, item.titleKey, item.title);
                            const itemSection = getTranslatedValue(t, item.sectionKey, item.section);

                            return (
                              <li key={item.id}>
                                <button
                                  type="button"
                                  onClick={() => handleQuickResultSelect(item)}
                                  className="flex w-full items-center gap-3 rounded-md px-2 py-2 text-left transition hover:bg-[var(--svs-cyan-surface)]"
                                >
                                  {item.image ? (
                                    <img
                                      src={item.image}
                                      alt={itemTitle}
                                      className="h-9 w-9 shrink-0 rounded-md object-cover"
                                      loading="lazy"
                                    />
                                  ) : (
                                    <Store className="h-5 w-5 shrink-0 text-[var(--svs-primary)]" />
                                  )}
                                  <span className="min-w-0 flex-1">
                                    <p className="whitespace-normal break-words text-sm font-semibold leading-tight">{itemTitle}</p>
                                    <p className="mt-0.5 whitespace-normal break-words text-xs leading-snug text-[var(--svs-muted)]">{itemSection}</p>
                                  </span>
                                  <ExternalLink className="h-4 w-4 shrink-0 text-[var(--svs-muted)]" />
                                </button>
                              </li>
                            );
                          })}
                        </ul>
                      ) : (
                        <p className="px-1 py-2 text-xs text-[var(--svs-muted)]">
                          {isQuickSearchLoading ? 'Searching our directory…' : 'No matching items in our directory.'}
                        </p>
                      )}
                      <button
                        type="button"
                        onClick={() => handleQuickSelect(query.trim())}
                        className="mt-2 inline-flex w-full items-center justify-center gap-1.5 rounded-md border border-[var(--svs-primary)] bg-[var(--svs-cyan-surface)] px-3 py-1.5 text-[11px] font-bold text-[var(--svs-primary-strong)] transition hover:bg-[var(--svs-primary)] hover:text-white"
                      >
                        View all directory results for &ldquo;{query.trim()}&rdquo;
                        <ArrowUpRight className="h-3.5 w-3.5" />
                      </button>
                    </section>

                    <section className="rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-3">
                      <header className="mb-2 flex items-center gap-1.5">
                        <Sparkles className="h-3.5 w-3.5 text-purple-500" />
                        <p className="text-[11px] font-bold uppercase tracking-wide text-purple-600">
                          Ask AI about &ldquo;{query.trim()}&rdquo;
                        </p>
                      </header>
                      <ul className="grid grid-cols-1 gap-1 sm:grid-cols-2">
                        {AI_SEARCH_ENGINES.map((engine) => (
                          <li key={engine.id}>
                            <a
                              href={engine.buildUrl(query.trim())}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-start gap-2.5 rounded-md px-2 py-2 transition hover:bg-purple-50"
                            >
                              <Sparkles className="mt-0.5 h-4 w-4 shrink-0 text-purple-500" />
                              <span className="min-w-0 flex-1">
                                <p className="text-sm font-semibold leading-tight text-[var(--svs-text)]">{engine.name}</p>
                                <p className="text-[11px] leading-snug text-[var(--svs-muted)]">{engine.description}</p>
                              </span>
                            </a>
                          </li>
                        ))}
                      </ul>
                    </section>

                    <section className="rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-3">
                      <header className="mb-2 flex items-center gap-1.5">
                        <Globe className="h-3.5 w-3.5 text-[var(--svs-primary)]" />
                        <p className="text-[11px] font-bold uppercase tracking-wide text-[var(--svs-muted)]">
                          Search the entire web for &ldquo;{query.trim()}&rdquo;
                        </p>
                      </header>
                      <ul className="grid grid-cols-1 gap-1 sm:grid-cols-2">
                        {WEB_SEARCH_ENGINES.map((engine) => (
                          <li key={engine.id}>
                            <a
                              href={engine.buildUrl(query.trim())}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-start gap-2.5 rounded-md px-2 py-2 transition hover:bg-[var(--svs-cyan-surface)]"
                            >
                              <Search className="mt-0.5 h-4 w-4 shrink-0 text-[var(--svs-primary)]" />
                              <span className="min-w-0 flex-1">
                                <p className="text-sm font-semibold leading-tight text-[var(--svs-text)]">{engine.name}</p>
                                <p className="text-[11px] leading-snug text-[var(--svs-muted)]">{engine.description}</p>
                              </span>
                            </a>
                          </li>
                        ))}
                      </ul>
                    </section>
                  </div>
                )}
              </div>
            ) : null}
          </form>

          <div className="ml-auto flex items-center gap-2.5 text-[var(--svs-nav-text)] sm:gap-4">
            <div className="hidden items-center gap-3 lg:flex">
              <div className="relative" ref={desktopLanguageMenuRef}>
                <button
                  type="button"
                  onClick={() => {
                    setLanguageSearchQuery('');
                    setPendingLanguageCode(activeLanguage.code);
                    setFocusedLanguageIndex(SUPPORTED_LANGUAGES.findIndex((language) => language.code === activeLanguage.code));
                    setIsLanguageModalOpen((prev) => !prev);
                  }}
                  className="inline-flex items-center gap-2 rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] px-3 py-1.5 text-sm font-semibold transition hover:border-[var(--svs-primary)]"
                  aria-label={t('languageModal.title')}
                  aria-haspopup="menu"
                  aria-expanded={isLanguageModalOpen}
                >
                  <span>{activeLanguage.flag ? `${activeLanguage.flag} ` : ''}{activeLanguage.englishName}</span>
                  <ChevronDown className={`h-4 w-4 transition ${isLanguageModalOpen ? 'rotate-180' : ''}`} />
                </button>
                <LanguageSelectorPopover
                  isOpen={isLanguageModalOpen}
                  pendingLanguageCode={pendingLanguageCode}
                  focusedIndex={focusedLanguageIndex}
                  filteredLanguages={filteredLanguages}
                  searchQuery={languageSearchQuery}
                  onSearchQueryChange={setLanguageSearchQuery}
                  onSelect={async (code) => {
                    setPendingLanguageCode(code);
                    setFocusedLanguageIndex(filteredLanguages.findIndex((language) => language.code === code));
                    await applyLanguageCode(code);
                  }}
                  onFocusIndex={setFocusedLanguageIndex}
                  cardRefs={languageCardRefs}
                />
              </div>
              {!isSellerConsoleRoute ? <CurrencySelectorButton compact /> : null}
              <button
                type="button"
                onClick={toggleTheme}
                className="inline-flex items-center gap-2 rounded-full border border-[var(--svs-border)] bg-[var(--svs-surface)] px-3 py-1.5 text-sm font-semibold transition hover:border-[var(--svs-primary)]"
                aria-label={t('theme.toggleAria')}
              >
                {isDarkMode ? <Sun className="h-4 w-4 text-[var(--svs-primary)]" /> : <Moon className="h-4 w-4 text-[var(--svs-primary-strong)]" />}
                <span>{isDarkMode ? t('theme.light') : t('theme.dark')}</span>
              </button>
            </div>
            {!isSellerConsoleRoute ? (
              <>
                <Link to="/checkout" aria-label="Open cart and checkout" className="relative rounded-full p-2 transition hover:bg-[var(--svs-cyan-surface)]">
                  <ShoppingCart className={`h-6 w-6 ${cudyBluePrimaryIconClassName}`} />
                  {cartItemCount > 0 ? (
                    <span className="absolute -right-1 -top-1 inline-flex min-h-5 min-w-5 items-center justify-center rounded-full bg-[var(--svs-primary)] px-1 text-[10px] font-bold text-white">
                      {cartItemCount}
                    </span>
                  ) : null}
                </Link>
                <Link to="/wishlist" aria-label="Open wishlist" className="relative rounded-full p-2 transition hover:bg-[var(--svs-cyan-surface)]">
                  <Heart className={`h-6 w-6 ${cudyBluePrimaryIconClassName}`} />
                  {wishlistItemCount > 0 ? (
                    <span className="absolute -right-1 -top-1 inline-flex min-h-5 min-w-5 items-center justify-center rounded-full bg-[var(--svs-primary)] px-1 text-[10px] font-bold text-white">
                      {wishlistItemCount}
                    </span>
                  ) : null}
                </Link>
              </>
            ) : null}
            <div className="relative" ref={notificationsMenuRef}>
              <button
                type="button"
                aria-label="Notifications"
                onClick={() => {
                  setIsNotificationsOpen((prev) => !prev);
                }}
                className="relative rounded-full p-2 transition hover:bg-[var(--svs-cyan-surface)]"
              >
                <Bell className={`h-6 w-6 ${cudyBluePrimaryIconClassName}`} />
                {unreadNotificationsCount > 0 ? (
                  <span className="absolute -right-1 -top-1 inline-flex min-h-5 min-w-5 items-center justify-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white">
                    {unreadNotificationsCount > 99 ? '99+' : unreadNotificationsCount}
                  </span>
                ) : null}
              </button>

              {isNotificationsOpen ? (
                <div className="absolute right-0 top-[calc(100%+8px)] z-[70] w-[min(88vw,300px)] overflow-hidden rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface)] shadow-2xl sm:w-[min(92vw,380px)] sm:rounded-2xl">
                  <div className="flex items-center justify-between border-b border-[var(--svs-border)] px-2 py-2 sm:px-4 sm:py-3">
                    <p className="text-xs font-bold text-[var(--svs-text)] sm:text-sm">Notifications</p>
                    <div className="flex items-center gap-2 sm:gap-3">
                      <p className="text-[10px] text-[var(--svs-muted)] sm:text-xs">{unreadNotificationsCount} unread</p>
                      {unreadNotificationsCount > 0 ? (
                        <button
                          type="button"
                          onClick={() => onMarkNotificationsRead?.()}
                          className="text-[10px] font-semibold text-[var(--svs-primary-strong)] transition hover:underline sm:text-xs"
                        >
                          Mark all read
                        </button>
                      ) : null}
                      {notifications.length > 0 ? (
                        <button
                          type="button"
                          onClick={() => { onClearNotifications?.(); setIsNotificationsOpen(false); }}
                        >
                          Clear All
                        </button>
                      ) : null}
                    </div>
                  </div>
                  <div className="flex items-center gap-2 px-2 py-1.5 sm:px-4 sm:py-2">
                    <span className="text-[var(--svs-muted)] text-[11px] font-medium sm:text-sm">Price</span>
                    <span className="ml-auto text-[var(--svs-muted)] text-[10px] sm:text-xs">{priceRange[0]}</span>
                    <span className="text-[var(--svs-muted)] text-[10px] sm:text-xs">-</span>
                    <span className="text-[var(--svs-muted)] text-[10px] sm:text-xs">{priceRange[1]}</span>
                  </div>
                  <div className="max-h-64 overflow-y-auto p-1.5 sm:max-h-80 sm:p-2">
                    {notifications.length ? notifications.map((notification) => (
                      <Link
                        key={notification.id}
                        to={notification.href || '/orders'}
                        onClick={() => {
                          onRemoveNotification?.(notification.id);
                          setIsNotificationsOpen(false);
                        }}
                        className={`mb-1 block rounded-lg border px-2 py-1.5 text-left transition last:mb-0 sm:rounded-xl sm:px-3 sm:py-2.5 ${
                          notification.read
                            ? 'border-transparent bg-[var(--svs-surface-soft)] hover:border-[var(--svs-primary)]'
                            : 'border-[var(--svs-primary)]/35 bg-[var(--svs-cyan-surface)]/70 hover:border-[var(--svs-primary)]'
                        }`}
                      >
                        <div className="flex items-start gap-2">
                          {!notification.read ? (
                            <span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[var(--svs-primary)]" aria-label="Unread notification" />
                          ) : null}
                          <div className="min-w-0 flex-1">
                            <p className="text-xs font-semibold text-[var(--svs-text)] sm:text-sm">{notification.title}</p>
                            {notification.message ? <p className="mt-0.5 text-[10px] text-[var(--svs-muted)] sm:text-xs">{notification.message}</p> : null}
                            <p className="mt-1 text-[10px] text-[var(--svs-muted)] sm:text-[11px]">{formatTimestampWithSeconds(notification.createdAt)}</p>
                          </div>
                        </div>
                      </Link>
                    )) : (
                      <p className="px-2 py-2 text-xs text-[var(--svs-muted)] sm:py-3 sm:text-sm">No notifications yet.</p>
                    )}
                  </div>
                </div>
              ) : null}
            </div>
            <div className="relative">
              <button
                type="button"
                aria-label="User profile"
                onClick={() => {
                  if (!isAuthenticated) {
                    navigate('/signin');
                    return;
                  }

                  setProfileOpen((prev) => !prev);
                }}
                className="rounded-full bg-[var(--svs-cyan-surface)] p-2"
              >
                <User className="h-6 w-6" />
              </button>

              {isAuthenticated && profileOpen ? (
                <div className="absolute right-0 top-[calc(100%+8px)] z-[80] w-56 rounded-xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-3 shadow-xl">
                  <p className="text-xs uppercase tracking-wide text-[var(--svs-muted)]">{t('profile.signedInAs')}</p>
                  <p className="mt-1 text-sm font-bold text-[var(--svs-text)]">{profileName}</p>
                  <Link
                    to="/wallet"
                    onClick={() => setProfileOpen(false)}
                    className="mt-3 flex w-full items-center gap-2 rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2 text-sm font-semibold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)]"
                  >
                    <Wallet className="h-4 w-4 text-[var(--svs-primary)]" />
                    My Wallet
                  </Link>
                  <Link
                    to="/account"
                    onClick={() => setProfileOpen(false)}
                    className="mt-2 flex w-full items-center gap-2 rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2 text-sm font-semibold text-[var(--svs-text)] transition hover:border-[var(--svs-primary)]"
                  >
                    <Settings className="h-4 w-4 text-[var(--svs-primary)]" />
                    Account Settings
                  </Link>
                  <button
                    type="button"
                    onClick={handleLogout}
                    className="mt-2 w-full rounded-md border border-[#fca5a5] bg-[#fff1f2] px-3 py-2 text-sm font-semibold text-[#b91c1c] transition hover:bg-[#ffe4e6]"
                  >
                    {t('profile.logout')}
                  </button>
                </div>
              ) : null}
            </div>
          </div>
        </div>

        {mobileOpen ? (
          <div className="border-t border-[var(--svs-border)] bg-[var(--svs-surface)] px-4 py-3 lg:hidden">
            <button
              type="button"
              onClick={toggleTheme}
              className="mb-3 inline-flex items-center gap-2 rounded-md border border-[var(--svs-border)] bg-[var(--svs-cyan-surface)] px-3 py-2 text-sm font-semibold"
            >
              {isDarkMode ? <Sun className="h-4 w-4 text-[var(--svs-primary)]" /> : <Moon className="h-4 w-4 text-[var(--svs-primary-strong)]" />}
              {t('theme.switchTo', { mode: isDarkMode ? t('theme.light') : t('theme.dark') })}
            </button>
            <div className="relative mb-3" ref={mobileLanguageMenuRef}>
              <button
                type="button"
                onClick={() => {
                  setLanguageSearchQuery('');
                  setPendingLanguageCode(activeLanguage.code);
                  setFocusedLanguageIndex(SUPPORTED_LANGUAGES.findIndex((language) => language.code === activeLanguage.code));
                  setIsLanguageModalOpen((prev) => !prev);
                }}
                className="flex w-full items-center justify-between rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2 text-left text-sm font-semibold"
                aria-haspopup="menu"
                aria-expanded={isLanguageModalOpen}
              >
                <span>{activeLanguage.flag ? `${activeLanguage.flag} ` : ''}{activeLanguage.englishName}</span>
                <ChevronDown className={`h-4 w-4 transition ${isLanguageModalOpen ? 'rotate-180' : ''}`} />
              </button>
              <LanguageSelectorPopover
                isOpen={isLanguageModalOpen}
                pendingLanguageCode={pendingLanguageCode}
                focusedIndex={focusedLanguageIndex}
                filteredLanguages={filteredLanguages}
                searchQuery={languageSearchQuery}
                onSearchQueryChange={setLanguageSearchQuery}
                onSelect={async (code) => {
                  setPendingLanguageCode(code);
                  setFocusedLanguageIndex(filteredLanguages.findIndex((language) => language.code === code));
                  setMobileOpen(false);
                  await applyLanguageCode(code);
                }}
                onFocusIndex={setFocusedLanguageIndex}
                cardRefs={languageCardRefs}
              />
            </div>
            {!isSellerConsoleRoute ? (
              <div className="mb-3">
                <CurrencySelectorButton className="block" />
              </div>
            ) : null}
            <div className="space-y-2 text-sm font-semibold">
              {isSellerConsoleRoute ? sellerConsoleNavItems.map((item) => (
                <Link
                  key={item.href}
                  to={item.href}
                  onClick={() => setMobileOpen(false)}
                  className="block rounded-md bg-[var(--svs-surface-soft)] px-3 py-2"
                >
                  {item.label}
                </Link>
              )) : navItems.map((item) => (
                <Link
                  key={item.labelKey}
                  to={item.href}
                  onClick={() => setMobileOpen(false)}
                  className="block rounded-md bg-[var(--svs-surface-soft)] px-3 py-2"
                >
                  {t(item.labelKey)}
                </Link>
              ))}
              {isSellerConsoleRoute ? (
                <Link
                  to="/markets"
                  onClick={() => setMobileOpen(false)}
                  className="block rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2 font-bold text-[var(--svs-text)]"
                >
                  Switch to Buyer View
                </Link>
              ) : hasSellerAccess ? (
                <Link
                  to={sellerHomePath}
                  onClick={() => setMobileOpen(false)}
                  className="block rounded-md border border-[var(--svs-border)] bg-[var(--svs-surface-soft)] px-3 py-2 font-bold text-[var(--svs-text)]"
                >
                  Switch to Seller View
                </Link>
              ) : (
                <Link
                  to="/sell"
                  onClick={() => setMobileOpen(false)}
                  className="block rounded-md bg-orange-500 px-3 py-2 font-bold text-white"
                >
                  Sell on SVS
                </Link>
              )}
              {!isAuthenticated ? (
                <>
                  <Link to="/signin" className="block rounded-md bg-[var(--svs-surface-soft)] px-3 py-2">
                    {t('profile.signIn')}
                  </Link>
                  <Link to="/signup" className="block rounded-md bg-[var(--svs-surface-soft)] px-3 py-2">
                    {t('profile.signUp')}
                  </Link>
                </>
              ) : null}
            </div>
          </div>
        ) : null}
      </header>

      <main id="main-content" className="pt-20">{children}</main>
      <SiteFooter />
    </div>
  );
};

const HomePage = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const isAuthenticated = getAuthState();
  const [activeSlide, setActiveSlide] = useState(0);
  const touchStartX = useRef(null);

  const [activeFeatureSlide, setActiveFeatureSlide] = useState(0);
  const featureTouchStartX = useRef(null);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setActiveFeatureSlide((prev) => (prev + 1) % featureSlides.length);
    }, 5000);
    return () => window.clearInterval(timer);
  }, []);

  const goToFeatureSlide = (index) => {
    const normalized = (index + featureSlides.length) % featureSlides.length;
    setActiveFeatureSlide(normalized);
  };

  const handleFeatureTouchStart = (e) => {
    featureTouchStartX.current = e.touches[0].clientX;
  };

  const handleFeatureTouchEnd = (e) => {
    if (featureTouchStartX.current === null) return;
    const diff = featureTouchStartX.current - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) {
      goToFeatureSlide(activeFeatureSlide + (diff > 0 ? 1 : -1));
    }
    featureTouchStartX.current = null;
  };

  const handleTouchStart = (e) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e) => {
    if (touchStartX.current === null) return;
    const diff = touchStartX.current - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) {
      goToSlide(activeSlide + (diff > 0 ? 1 : -1));
    }
    touchStartX.current = null;
  };

  useEffect(() => {
    const timer = window.setInterval(() => {
      setActiveSlide((prev) => (prev + 1) % homeHeroSlides.length);
    }, 5000);
    return () => window.clearInterval(timer);
  }, []);

  const goToSlide = (index) => {
    const normalized = (index + homeHeroSlides.length) % homeHeroSlides.length;
    setActiveSlide(normalized);
  };

  const slide = homeHeroSlides[activeSlide];

  // Map slide id or route to a more relevant page if needed
  const getLearnMoreRoute = (slide) => {
    // Example: customize for specific slides if needed
    // Default: use slide.route
    if (slide.route) return slide.route;
    // fallback: homepage
    return '/';
  };

  return (
    <>
      <section
        className="relative overflow-hidden bg-[#000000] px-3 py-3 text-white sm:px-4 sm:py-16 lg:py-24"
        onTouchStart={handleTouchStart}
        onTouchEnd={handleTouchEnd}
      >
        <div className="absolute inset-0 bg-gradient-to-br from-black via-[#141424] to-[#0a2030]" aria-hidden="true" />
        <div className="mx-auto w-full max-w-7xl">
          {/* Mobile uses the SAME structure as desktop but compressed: shorter
              image, smaller fonts/paddings — visually a miniaturised version
              of the full-screen desktop hero rather than a re-stacked card. */}
          <div className="relative overflow-hidden rounded-xl border border-white/10 sm:rounded-3xl">
            <img
              src={slide.image}
              alt={slide.title}
              className="h-[140px] w-full object-cover sm:h-[420px] md:h-[520px]"
              loading="eager"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/40 to-black/20" />

            <div className="absolute inset-0 flex flex-col items-center justify-center px-2 text-center sm:px-4">
              <p className="rounded-full bg-[var(--svs-primary)] px-1.5 py-[1px] text-[8px] font-semibold text-white sm:px-4 sm:py-1 sm:text-sm">{slide.label}</p>
              <h1 className="mt-1 text-[13px] font-bold leading-tight text-white sm:mt-4 sm:text-4xl md:text-5xl lg:text-6xl">{slide.title}</h1>
              <p className="mt-0.5 text-[8px] leading-snug text-slate-100 sm:mt-3 sm:text-lg md:text-2xl">{slide.subtitle}</p>
              <button
                type="button"
                onClick={() => navigate(getLearnMoreRoute(slide))}
                className={`${cudyBluePrimaryButtonClassName} mt-1.5 rounded-full bg-[var(--svs-primary)] px-2.5 py-1 text-[9px] font-semibold text-white shadow-lg transition hover:scale-105 hover:bg-[#33b9f2] sm:mt-6 sm:px-8 sm:py-3 sm:text-base`}
              >
                {t('common.learnMore')}
              </button>
            </div>

            <button
              type="button"
              onClick={() => goToSlide(activeSlide - 1)}
              className="absolute left-1.5 top-1/2 -translate-y-1/2 rounded-full bg-black/35 p-1 text-white transition hover:bg-black/60 sm:left-3 sm:p-2"
              aria-label="Previous slide"
            >
              <ChevronLeft className="h-3 w-3 sm:h-5 sm:w-5" />
            </button>
            <button
              type="button"
              onClick={() => goToSlide(activeSlide + 1)}
              className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded-full bg-black/35 p-1 text-white transition hover:bg-black/60 sm:right-3 sm:p-2"
              aria-label="Next slide"
            >
              <ChevronRight className="h-3 w-3 sm:h-5 sm:w-5" />
            </button>

            <div className="absolute bottom-1.5 left-1/2 flex -translate-x-1/2 items-center gap-1.5 sm:bottom-4 sm:gap-2">
              {homeHeroSlides.map((hero, index) => (
                <button
                  key={hero.id}
                  type="button"
                  onClick={() => goToSlide(index)}
                  className={`h-2 rounded-full transition-all sm:h-2.5 ${index === activeSlide ? 'w-5 bg-[var(--svs-primary)] sm:w-6' : 'w-2 bg-white/50 sm:w-2.5'}`}
                  aria-label={`Go to slide ${index + 1}`}
                />
              ))}
            </div>
          </div>
        </div>
      </section>

      <section className="h-10 bg-gradient-to-b from-[var(--svs-bg)] to-[var(--svs-surface-soft)]" />

      <RecentlyViewedStrip />

      <section className="bg-[var(--svs-surface-soft)] px-4 py-12">
        <div className="mx-auto w-full max-w-4xl text-center">
          <h2 className="text-3xl font-bold text-[var(--svs-text)] sm:text-4xl">What SVS E-COMMERCE Offers</h2>
          <div className="mt-5 rounded-2xl border border-[var(--svs-border)] bg-[var(--svs-surface)] p-6 shadow-[0_4px_8px_rgba(0,0,0,0.08)]">
            <p className="mt-4 text-base leading-7 text-[var(--svs-muted)] sm:text-lg">
              Shop, order, and book service provider you need - all in one intelligent platform. From daily essentials,
              food, and medicines to groceries, liquor, and tickets - enjoy a smooth, AI-powered experience with
              real-time tracking, personalized recommendations, and secure payments designed for your convenience.
            </p>
          </div>
        </div>
      </section>

      <section
        className="bg-white px-4 py-12"
        onTouchStart={handleFeatureTouchStart}
        onTouchEnd={handleFeatureTouchEnd}
      >
        <div className="mx-auto grid w-full max-w-7xl gap-8 lg:grid-cols-2 lg:items-center">
          <div className="relative overflow-hidden rounded-2xl border border-[#e5e7eb] bg-[#f3f6fb] shadow-[0_4px_12px_rgba(0,0,0,0.1)]">
            <img
              src={featureSlides[activeFeatureSlide].image}
              alt={featureSlides[activeFeatureSlide].title}
              className="h-[380px] w-full object-cover transition-opacity duration-500"
              loading="lazy"
            />
            <button
              type="button"
              onClick={() => goToFeatureSlide(activeFeatureSlide - 1)}
              className="absolute left-3 top-1/2 -translate-y-1/2 rounded-full bg-black/35 p-2 text-white transition hover:bg-black/60"
              aria-label="Previous slide"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              type="button"
              onClick={() => goToFeatureSlide(activeFeatureSlide + 1)}
              className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full bg-black/35 p-2 text-white transition hover:bg-black/60"
              aria-label="Next slide"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
            <div className="absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-2">
              {featureSlides.map((fs, index) => (
                <button
                  key={fs.id}
                  type="button"
                  onClick={() => goToFeatureSlide(index)}
                  className={`h-2.5 w-2.5 rounded-full transition ${index === activeFeatureSlide ? 'bg-[var(--svs-primary)]' : 'bg-white/60'}`}
                  aria-label={`Go to slide ${index + 1}`}
                />
              ))}
            </div>
          </div>

          <div>
            <h2 className="text-3xl font-bold text-[#111827] sm:text-4xl">{featureSlides[activeFeatureSlide].title}</h2>
            <p className="mt-4 text-lg leading-8 text-[#555555]">
              {featureSlides[activeFeatureSlide].subtitle}
            </p>
            <div className="mt-7 flex flex-wrap gap-3">
              <Link
                to={featureSlides[activeFeatureSlide].route || '/markets'}
                className={`${cudyBluePrimaryButtonClassName} rounded-md bg-[var(--svs-primary)] px-6 py-3 text-base font-semibold text-white shadow transition hover:scale-105 hover:bg-[#33b9f2]`}
              >
                {t('common.exploreNow')}
              </Link>
              {!isAuthenticated ? (
                <Link
                  to="/signup"
                  className={`${cudyBluePrimaryOutlineClassName} rounded-md border border-[var(--svs-primary)] px-6 py-3 text-base font-semibold text-[var(--svs-primary)] transition hover:scale-105 hover:bg-[#e0f7fa]`}
                >
                  {t('profile.signUp')}
                </Link>
              ) : null}
            </div>
          </div>
        </div>
      </section>
    </>
  );
};

